scription: "Datadog, New Relic, Prometheus, CloudWatch"\n      - fieldname: metricsStore\n        description: "InfluxDB, Prometheus, CloudWatch Metrics"\n      - fieldname: tracingPlatform\n        description: "Jaeger, Zipkin, AWS X-Ray, Datadog APM"\n      - fieldname: loggingPlatform\n        description: "ELK Stack, Loki, CloudWatch Logs"\n      - fieldname: coverageRequirement\n        description: Which services must be monitored\n      - fieldname: dataRetention\n        description: "Metrics: 15d, traces: 7d, logs: 30d"\n      - fieldname: costBudget\n        description: Monthly monitoring cost budget\n  hcec-form:\n    fields:\n      - fieldname: healthCheckPort\n        description: Dedicated health check port\n      - fieldname: responseFormat\n        description: "JSON, plain text, RFC Health Check format"\n      - fieldname: successStatusCode\n        description: HTTP 200 for healthy\n      - fieldname: failureStatusCode\n        description: HTTP 503 for unhealthy\n  hcet-form:\n    fields:\n      - fieldname: checkInterval\n        description: "How often health is checked (e.g. 10s, 30s)"\n      - fieldname: checkTimeout\n        description: Max time for a health check response\n      - fieldname: failureThreshold\n        description: Consecutive failures before unhealthy\n      - fieldname: successThreshold\n        description: Consecutive successes to become healthy\n  hechenco-form:\n    fields:\n      - fieldname: includeComponentStatus\n        description: Show status of individual components\n      - fieldname: includeVersion\n        description: Include app version in response\n      - fieldname: includeUptime\n        description: Include process uptime\n      - fieldname: includeMetrics\n        description: Include basic metrics in response\n      - fieldname: sensitiveDataRedaction\n        description: Redact secrets from health output\n      - fieldname: notes\n        description: Additional health endpoint notes\n  apdipe-form