 fieldname: users36Months\n        description: Expected active users in 36 months\n  ugps-form:\n    fields:\n      - fieldname: userSegments\n        description: "Growth per user category (free, premium, enterprise)"\n      - fieldname: geographicDistribution\n        description: Expected user distribution across regions\n      - fieldname: seasonalPatterns\n        description: Monthly/quarterly user volume patterns\n  ugpt-form:\n    fields:\n      - fieldname: softCapacityLimit\n        description: User count requiring system review\n      - fieldname: hardCapacityLimit\n        description: Maximum supportable users before scaling\n      - fieldname: notes\n        description: Additional user growth notes\n  dgpg-form:\n    fields:\n      - fieldname: dataGrowthRate\n        required: true\n        description: Monthly data volume increase\n      - fieldname: dataVolumePerUser\n        description: Average storage per active user\n      - fieldname: transactionVolumeGrowth\n        description: Growth in daily/monthly transactions\n  dgpp-form:\n    fields:\n      - fieldname: projectedVolume6Months\n        description: Expected total data at 6 months\n      - fieldname: projectedVolume12Months\n        description: Expected total data at 12 months\n      - fieldname: projectedVolume24Months\n        description: Expected total data at 24 months\n  dgpl-form:\n    fields:\n      - fieldname: dataRetentionPolicy\n        description: Hot/warm/cold storage tiers\n      - fieldname: archivalStrategy\n        description: When and how data moves to archive\n      - fieldname: dataCleanupPolicy\n        description: Automatic deletion rules\n      - fieldname: compressionStrategy\n        description: Data compression for storage efficiency\n  dgpt-form:\n    fields:\n      - fieldname: storageAlertThreshold\n        description: "Percentage triggering storage alert (e.g. 80%)"\n      - fieldname: partitioningStrategy\n        description: Table/index partitio