nning instances\n      - fieldname: maxInstances\n        description: Maximum number of running instances\n      - fieldname: scalingStepSize\n        description: Instances added per scale-up event\n  statt-form:\n    fields:\n      - fieldname: horizontalScaling\n        description: Add more instances\n      - fieldname: verticalScaling\n        description: Increase instance resources\n      - fieldname: autoScalingProvider\n        description: "Kubernetes HPA, AWS Auto Scaling, Azure VMSS"\n      - fieldname: scheduledScaling\n        description: Pre-scale for known peak events\n      - fieldname: notes\n        description: Additional scaling trigger notes\n  rcbs-form:\n    fields:\n      - fieldname: storageIOPSBaseline\n        description: Normal storage I/O operations per second\n      - fieldname: storageThroughputBaseline\n        description: Normal storage throughput (MB/s)\n  rcbn-form:\n    fields:\n      - fieldname: networkBandwidthBaseline\n        description: Normal network usage (Mbps)\n      - fieldname: connectionCountBaseline\n        description: Normal active connection count\n  rcbd-form:\n    fields:\n      - fieldname: databaseConnectionPoolBaseline\n        description: Normal active DB connections\n      - fieldname: queryVolumeBaseline\n        description: Normal queries per second\n      - fieldname: databaseSizeBaseline\n        description: Current database on-disk size\n  rcbc-form:\n    fields:\n      - fieldname: currentMonthlyCost\n        description: Baseline monthly infrastructure cost\n      - fieldname: costPerUser\n        description: Infrastructure cost per active user\n      - fieldname: projectedCostAtScale\n        description: Estimated cost at target user count\n      - fieldname: notes\n        description: Additional resource baseline notes\n  careprmo-form:\n    fields:\n      - fieldname: capacityDashboard\n        description: Dedicated capacity monitoring dashboard\n      - fieldname: trendAnalysis\n        description: Automated growth trend detection\n      - fieldname: forecastingModel\n        description: "Linear, exponential, ML-based forecasting"\n  crpe-form:\n    fields:\n      - fieldname: capacityAlertThresholds\n        description: "Warning: 70%, critical: 85%, emergency: 95%"\n      - fieldname: escalationProcedure\n        description: Who to notify at each threshold level\n      - fieldname: emergencyScalingProcedure\n        description: Steps for urgent capacity increase\n  crpp-form:\n    fields:\n      - fieldname: budgetPlanningIntegration\n        description: Capacity forecasts feed into budget cycles\n      - fieldname: procurementLeadTime\n        description: Time to provision new resources\n      - fieldname: rightsizingReview\n        description: Periodic over-provisioning review\n      - fieldname: notes\n        description: Additional capacity review notes\n  sestensc-form:\n    fields:\n      - fieldname: applicabilityScope\n        description: "Which systems, services, or data this applies to"\n      - fieldname: mandatoryOrVoluntary\n        description: Regulatory requirement or best-practice adoption\n      - fieldname: regulatoryDriver\n        description: "Regulation requiring this standard (e.g. GDPR, PCI-DSS)"\n  ssei-form:\n    fields:\n      - fieldname: implementationStatus\n        description: "Planned, In Progress, Implemented, Certified"\n      - fieldname: targetComplianceDate\n        description: Date by which compliance must be achieved\n      - fieldname: controlsRequired\n        description: Key control areas to implement\n      - fieldname: gapAnalysis\n        description: Summary of current gaps against the standard\n  ssev-form:\n    fields:\n      - fieldname: certificationRequired\n        description: Whether formal certification is needed\n      - fieldname: assessmentFrequency\n        description: How often compliance is assessed\n      - fieldname: evidenceRequirements\n        description: Documentation and artifacts to maintain\n      - fieldname: responsibleTeam\n        description: Team/role accountable for compliance\n      - fieldname: notes\n        description: Additional security standard notes\n  asrc-form:\n    fields:\n      - fieldname: sensitiveDataExposure\n        description: "Encryption, masking, tokenization"\n      - fieldname: accessControlEnforcement\n        description: Broken access control prevention\n      - fieldname: securityMisconfiguration\n        description: "Default credentials, open ports, debug mode"\n      - fieldname: csrfProtection\n        description: Cross-site request forgery prevention\n      - fieldname: ssrfProtection\n        description: Server-side request forgery prevention\n  asrv-form:\n    fields:\n      - fieldname: inputValidationStrategy\n        description: "Whitelist, sanitization, encoding"\n      - fieldname: outputEncoding\n        description: "HTML, URL, JavaScript encoding"\n      - fieldname: fileUploadSecurity\n        description: "File type, size, malware scanning"\n  asra-form:\n    fields:\n      - fieldname: apiSecurityStandard\n        description: OWASP API Security Top 10 measures\n      - fieldname: rateLimiting\n        description: API rate limiting and throttling\n      - fieldname: contentSecurityPolicy\n        description: CSP headers and directives\n      - fieldname: notes\n        description: Additional application security notes\n  ishc-form:\n    fields:\n      - fieldname: containerBaseImages\n        description: "Approved base images, distroless, Alpine"\n      - fieldname: containerScanning\n        description: Image vulnerability scanning tool\n      - fieldname: containerRuntimeSecurity\n        description: "Read-only filesystems, non-root, capabilities"\n      - fieldname: containerOrchestrationSecurity\n        description: "K8s RBAC, network policies, pod security"\n  ishn-form:\n    fields:\n      - fieldname: networkSegmentation\n        description: "VPC, subnet, security group strategy"\n      - fieldname: internalTlsCommunication\n        description: Service-to-service mTLS\n      - fieldname: dnsSecurityPolicy\n        description: "DNSSEC, private DNS zones"\n  isha-form:\n    fields:\n      - fieldname: sshAccessPolicy\n        description: "Key-only auth, bastion hosts, session recording"\n      - fieldname: privilegedAccessManagement\n        description: "PAM tool, just-in-time access"\n      - fieldname: serviceAccountPolicy\n        description: "Least privilege, rotation, naming"\n      - fieldname: notes\n        description: Additional infrastructure security notes\n  sdld-form:\n    fields:\n      - fieldname: secureCodeTraining\n        description: Developer security training frequency\n      - fieldname: staticAnalysis\n        description: SAST tool and integration point\n      - fieldname: secretDetection\n        description: "Pre-commit hooks, CI scanning for secrets"\n      - fieldname: dependencyScanning\n        description: SCA tool for known vulnerabilities\n      - fieldname: licenseScannerPolicy\n        description: OSS license compatibility checking\n  sdlt-form:\n    fields:\n      - fieldname: dynamicAnalysis\n        description: DAST tool and test frequency\n      - fieldname: interactiveAnalysis\n        description: IAST tool for runtime detection\n      - fieldname: securityTestingInCi\n        description: Automated security tests in pipeline\n      - fieldname: manualCodeReview\n        description: Security-focused code review process\n  sdlr-form:\n    fields:\n      - fieldname: preReleaseSecurityGate\n        description: Security sign-off before production deploy\n      - fieldname: securityChangeLog\n        description: Track security-relevant changes\n      - fieldname: notes\n        description: Additional security dev lifecycle notes\n  vmpc-form:\n    fields:\n      - fieldname: severityClassification\n        description: "CVSS-based: Critical, High, Medium, Low"\n      - fieldname: criticalVulnSla\n        description: Max time to patch critical (e.g. 24h)\n      - fieldname: highVulnSla\n        description: Max time to patch high (e.g. 7d)\n      - fieldname: mediumVulnSla\n        description: Max time to patch medium (e.g. 30d)\n      - fieldname: lowVulnSla\n        description: Max time to patch low (e.g. 90d)\n  vmpp-form:\n    fields:\n      - fieldname: vulnerabilityTracking\n        description: "Jira, dedicated vulnerability tool"\n      - fieldname: riskAcceptanceProcess\n        description: When and how to accept residual risk\n      - fieldname: exceptionProcess\n        description: Temporary exception workflow and approvals\n      - fieldname: zeroDayResponsePlan\n        description: Emergency response for zero-day exploits\n  vmpr-form:\n    fields:\n      - fieldname: vulnerabilityReporting\n        description: "Dashboard, weekly report, executive summary"\n      - fieldname: responsibleDisclosure\n        description: "Bug bounty, security.txt, disclosure policy"\n      - fieldname: notes\n        description: Additional vulnerability management notes\n  irpp-form:\n    fields:\n      - fieldname: initialResponseSla\n        description: Time to acknowledge and begin triage\n      - fieldname: containmentProcedure\n        description: Steps to isolate affected systems\n      - fieldname: eradicationProcedure\n        description: Steps to remove threat from systems\n      - fieldname: recoveryProcedure\n        description: Steps to restore normal operations\n  irpc-form:\n    fields:\n      - fieldname: notificationRequirements\n        description: Regulatory breach notification timelines\n      - fieldname: internalEscalation\n        description: Escalation paths and contacts\n      - fieldname: externalCommunication\n        description: "Customer notification, press, regulators"\n      - fieldname: legalCounselEngagement\n        description: When to engage legal team\n  irppi-form:\n    fields:\n      - fieldname: postIncidentReview\n        description: Blameless retrospective process\n      - fieldname: lessonsLearnedProcess\n        description: How findings are fed back into prevention\n      - fieldname: incidentDocumentation\n        description: What to document and retention period\n      - fieldname: notes\n        description: Additional incident response notes\n  prcg-form:\n    fields:\n      - fieldname: gdprLawfulBasis\n        description: "Consent, contract, legal obligation, vital interests, public task, legitimate interests"\n      - fieldname: gdprDataControllerRole\n        required: true\n        description: Whether organization acts as controller or processor\n      - fieldname: gdprRepresentative\n        description: EU-based representative if organization is outside EU\n      - fieldname: gdprLeadSupervisoryAuthority\n        description: Lead supervisory authority for cross-border processing\n  prcd-form:\n    fields:\n      - fieldname: dpoRequired\n        description: Whether a Data Protection Officer is required\n      - fieldname: dpoContactDetails\n        description: "Name, email, and reporting line of DPO"\n      - fieldname: dpoResponsibilities\n        description: "Monitoring compliance, advising on DPIA, liaison with authority"\n  prcr-form:\n    fields:\n      - fieldname: recordsOfProcessing\n        required: true\n        description: ROPA maintenance process — Article 30 GDPR\n      - fieldname: privacyPolicyRequirements\n        description: "Transparency notices, layered privacy policies"\n      - fieldname: dataProtectionTraining\n        description: "Staff training frequency, content, and certification"\n  prct-form:\n    fields:\n      - fieldname: crossBorderTransferMechanism\n        description: "Standard contractual clauses, adequacy decisions, binding corporate rules"\n      - fieldname: transferImpactAssessment\n        description: "Assessment of third-country legal framework, Schrems II"\n      - fieldname: notes\n        description: Additional regulation compliance notes\n  drrs-form:\n    fields:\n      - fieldname: dataResidencyRegulation\n        description: "Specific laws mandating data residency (e.g. Russia, China)"\n      - fieldname: dataSovereigntyRequirements\n        description: "Government access restrictions, national security considerations"\n      - fieldname: encryptionKeyLocation\n        required: true\n        description: Where encryption keys are stored and managed geographically\n      - fieldname: cloudProviderRequirements\n        description: "Sovereign cloud requirements, government-certified providers"\n  darerere-form:\n    fields:\n      - fieldname: backupDataResidency\n        description: Geographic constraints for backup and disaster recovery data\n      - fieldname: replicationConstraints\n        description: Cross-region replication limitations and rules\n      - fieldname: cdnDataConstraints\n        description: Content delivery network caching location restrictions\n  drrv-form:\n    fields:\n      - fieldname: residencyVerification\n        description: How data residency compliance is verified and audited\n      - fieldname: providerCertifications\n        description: "Cloud provider certifications (ISO 27001, SOC 2, C5, ENS)"\n      - fieldname: dataLocationTransparency\n        description: How data subjects are informed about storage locations\n      - fieldname: notes\n        description: Additional data residency notes\n  cmrc-form:\n    fields:\n      - fieldname: consentLanguage\n        description: "Plain language requirements, multi-language support, reading level"\n      - fieldname: doubleOptIn\n        description: Whether double opt-in is required (e.g. email verification)\n      - fieldname: ageVerification\n        description: "Minimum age requirements, parental consent for minors (COPPA, GDPR Art. 8)"\n  comarest-form:\n    fields:\n      - fieldname: consentVersioning\n        description: Tracking consent policy versions and re-consent triggers\n      - fieldname: consentProofRetention\n        description: How long consent proof is retained after withdrawal\n  cmrm-form:\n    fields:\n      - fieldname: consentPreferenceCenter\n        description: Self-service UI for managing consent preferences\n      - fieldname: consentPropagation\n        description: How consent changes propagate to downstream systems and processors\n      - fieldname: consentSynchronization\n        description: "Synchronizing consent across web, mobile, and third parties"\n  cmrt-form:\n    fields:\n      - fieldname: cookieConsentRequirements\n        description: "Cookie categories (essential, functional, analytics, marketing)"\n      - fieldname: trackingConsentRequirements\n        description: "Analytics, advertising pixels, fingerprinting consent requirements"\n      - fieldname: thirdPartyConsentSharing\n        description: How consent status is communicated to third-party integrations\n  comareco-form:\n    fields:\n      - fieldname: consentAuditTrail\n        description: Audit logging of all consent events for regulatory evidence\n      - fieldname: consentComplianceReporting\n        description: "Consent metrics, dashboards, and regulatory reports"\n      - fieldname: notes\n        description: Additional consent management notes\n  dsrma-form:\n    fields:\n      - fieldname: accessDataFormat\n        description: "Format for providing data (structured, machine-readable, PDF)"\n      - fieldname: rectificationProcess\n        description: How data subjects request correction of inaccurate personal data\n      - fieldname: rectificationPropagation\n        description: How corrections propagate to recipients of the data\n  dsrme-form:\n    fields:\n      - fieldname: erasureProcess\n        required: true\n        description: How erasure requests are processed — "right to be forgotten"\n      - fieldname: erasureScope\n        description: "What data is erased: active records, backups, logs, analytics"\n      - fieldname: erasureExceptions\n        description: "Legal retention obligations that override erasure (tax, fraud)"\n      - fieldname: erasureVerification\n        description: How complete erasure is verified across all systems\n  dsrmp-form:\n    fields:\n      - fieldname: portabilityProcess\n        required: true\n        description: "How data is exported in structured, machine-readable format"\n      - fieldname: portabilityFormat\n        description: "Export formats: JSON, CSV, XML, API-based transfer"\n      - fieldname: portabilityDirectTransfer\n        description: Whether direct controller-to-controller transfer is supported\n  dsrmr-form:\n    fields:\n      - fieldname: restrictionProcess\n        description: How processing restriction is applied while disputes are resolved\n      - fieldname: objectionProcess\n        description: "How objections to processing are handled (direct marketing, profiling)"\n  dasurimaau-form:\n    fields:\n      - fieldname: automatedDecisionMaking\n        description: Safeguards for automated decisions with legal or significant effects\n      - fieldname: humanReviewProcess\n        description: Process for requesting human review of automated decisions\n  dsrmo-form:\n    fields:\n      - fieldname: dsarWorkflow\n        description: Data Subject Access Request end-to-end workflow and tooling\n      - fieldname: dsarTracking\n        description: "Tracking system for requests, SLAs, and completion metrics"\n      - fieldname: notes\n        description: Additional data subject rights notes\n  piapa-form:\n    fields:\n      - fieldname: dpiaStakeholders\n        description: "Who participates: DPO, engineering, legal, business, external advisor"\n      - fieldname: dataFlowMapping\n        description: "Documenting data flows, storage, access, and sharing for each processing activity"\n      - fieldname: riskAssessmentCriteria\n        description: "Likelihood and severity matrix, residual risk thresholds"\n  piapm-form:\n    fields:\n      - fieldname: mitigationMeasures\n        description: Technical and organizational measures to reduce identified risks\n      - fieldname: privacyByDesign\n        required: true\n        description: How privacy is embedded in system design from inception (Art. 25 GDPR)\n      - fieldname: privacyByDefault\n        description: "Default settings protect privacy — minimal data, shortest retention"\n      - fieldname: dataMinimization\n        description: Limiting collection to what is necessary for the specified purpose\n      - fieldname: pseudonymization\n        description: "Techniques applied: tokenization, hashing, key-coded data"\n      - fieldname: anonymization\n        description: "Techniques for irreversible de-identification: k-anonymity, differential privacy"\n  piapr-form:\n    fields:\n      - fieldname: dpiaApprovalProcess\n        description: Who reviews and approves the DPIA before processing begins\n      - fieldname: supervisoryConsultation\n        description: When prior consultation with the supervisory authority is required\n      - fieldname: dpiaReviewFrequency\n        description: How often existing DPIAs are reviewed and updated\n      - fieldname: notes\n        description: Additional privacy impact assessment notes\n  dparm-form:\n    fields:\n      - fieldname: subProcessorManagement\n        description: "How sub-processors are approved, listed, and monitored"\n      - fieldname: subProcessorNotification\n        description: Process for notifying controllers of sub-processor changes\n  dparh-form:\n    fields:\n      - fieldname: dataRetentionInDpa\n        description: Retention periods and deletion/return obligations\n      - fieldname: dataReturnOnTermination\n        description: Data return or certified destruction on contract end\n      - fieldname: confidentialityObligations\n        description: Staff confidentiality commitments and access restrictions\n  dpars-form:\n    fields:\n      - fieldname: securityMeasuresInDpa\n        description: Technical and organizational measures required from processors\n      - fieldname: breachNotificationInDpa\n        description: Processor obligation to notify controller of breaches without undue delay\n      - fieldname: complianceCertification\n        description: Processor certifications accepted as audit evidence\n  dpart-form:\n    fields:\n      - fieldname: internationalTransferClauses\n        description: Standard contractual clauses or other mechanisms in the DPA\n      - fieldname: governingLaw\n        description: Applicable law and jurisdiction for DPA disputes\n      - fieldname: liabilityAndIndemnification\n        description: Liability allocation and indemnification provisions\n      - fieldname: notes\n        description: Additional data processing agreement notes\n  dpch-form:\n    fields:\n      - fieldname: encryptionAtRest\n        required: true\n        description: Encryption requirements per classification level (AES-256)\n      - fieldname: encryptionInTransit\n        required: true\n        description: "TLS 1.2+, mTLS, certificate requirements"\n      - fieldname: accessControlByClassification\n        description: Access restrictions mapped to classification levels\n      - fieldname: loggingByClassification\n        description: Audit logging requirements per classification level\n  dpcr-form:\n    fields:\n      - fieldname: retentionPolicyByCategory\n        required: true\n        description: Retention periods per data category and legal basis\n      - fieldname: disposalProcedure\n        description: "Secure deletion, shredding, crypto-erasure per classification"\n      - fieldname: retentionExceptions\n        description: "Legal holds, regulatory overrides, litigation preservation"\n  dpcm-form:\n    fields:\n      - fieldname: dataMaskingRules\n        description: "Masking rules for non-production environments, logs, and reports"\n      - fieldname: tokenizationRequirements\n        description: "Payment card, PII tokenization approach (PCI DSS)"\n      - fieldname: deIdentificationStandards\n        description: "HIPAA Safe Harbor, Expert Determination, k-anonymity"\n  dpci-form:\n    fields:\n      - fieldname: breachClassificationMatrix\n        description: Mapping data classification to breach severity and response\n      - fieldname: dataLossPreventionControls\n        description: Technical controls to prevent unauthorized data exfiltration\n      - fieldname: notes\n        description: Additional data protection classification notes\n  ptrs-form:\n    fields:\n      - fieldname: pentestFrequency\n        required: true\n        description: "Annual, semi-annual, quarterly, after major releases"\n      - fieldname: retestRequirements\n        description: When retesting is required after remediation\n      - fieldname: triggerBasedTesting\n        description: "Events triggering unscheduled tests: major changes, incidents, new integrations"\n  ptre-form:\n    fields:\n      - fieldname: testingEnvironment\n        description: "Production, staging, dedicated pentest environment"\n      - fieldname: rulesOfEngagement\n        description: "Boundaries, excluded systems, testing windows, escalation"\n      - fieldname: socialEngineeringScope\n        description: "Phishing, vishing, physical access testing if applicable"\n      - fieldname: dosTestingAllowed\n        description: Whether denial-of-service testing is in scope\n  ptrr-form:\n    fields:\n      - fieldname: findingSeverityScale\n        description: "CVSS, custom scale (Critical/High/Medium/Low/Info)"\n      - fieldname: reportingFormat\n        description: "Executive summary, technical findings, remediation guidance"\n      - fieldname: remediationTimelines\n        required: true\n        description: "SLAs per severity: Critical 48h, High 7d, Medium 30d, Low 90d"\n      - fieldname: managementBriefing\n        description: Post-test executive debrief requirements\n      - fieldname: notes\n        description: Additional penetration testing notes\n  scrpr-form:\n    fields:\n      - fieldname: securityReviewerRequirements\n        required: true\n        description: "Security training certifications, experience requirements for reviewers"\n      - fieldname: externalReviewCriteria\n        description: When external security review firm is engaged\n      - fieldname: reviewerRotation\n        description: How security reviewers are rotated to avoid bias\n  scrpp-form:\n    fields:\n      - fieldname: securityChecklist\n        description: "OWASP Top 10, injection, XSS, CSRF, auth bypass, data exposure"\n      - fieldname: threatModelingIntegration\n        description: How threat models inform code review focus areas\n      - fieldname: securityAnnotations\n        description: Code annotations marking security-critical sections for priority review\n  scrpf-form:\n    fields:\n      - fieldname: findingClassification\n        description: "Vulnerability, weakness, informational, best-practice deviation"\n      - fieldname: findingTrackingProcess\n        description: How findings are tracked from discovery to resolution\n      - fieldname: securityDebtManagement\n        description: How accepted security risks are documented and reviewed\n      - fieldname: notes\n        description: Additional security code review notes\n  dsrv-form:\n    fields:\n      - fieldname: vulnerabilityDatabase\n        description: "NVD, GitHub Advisory Database, OSV, vendor-specific advisories"\n      - fieldname: remediationSla\n        description: Time to patch per severity level\n      - fieldname: exceptionProcess\n        description: How vulnerabilities are risk-accepted with justification\n  dsrs-form:\n    fields:\n      - fieldname: sbomGeneration\n        description: "Software Bill of Materials format: SPDX, CycloneDX"\n      - fieldname: sbomUpdateFrequency\n        description: How often SBOM is regenerated and published\n      - fieldname: sbomDistribution\n        description: "Who receives SBOM: customers, auditors, regulators"\n  dsrl-form:\n    fields:\n      - fieldname: licensePolicy\n        description: "Allowed licenses (MIT, BSD, Apache 2.0), restricted (GPL, AGPL), review-required"\n      - fieldname: licenseScanning\n        description: Automated license detection and policy enforcement\n  dsrsc-form:\n    fields:\n      - fieldname: dependencyPinning\n        description: "Lock file requirements, version pinning strategy"\n      - fieldname: signatureVerification\n        description: "Package signature verification, provenance attestation"\n      - fieldname: privateRegistryPolicy\n        description: "Internal package registry, proxy settings, caching policy"\n      - fieldname: notes\n        description: Additional dependency scanning notes\n  scri-form:\n    fields:\n      - fieldname: iso27001Controls\n        description: "Annex A controls applicable, Statement of Applicability"\n      - fieldname: ismsScope\n        description: Information Security Management System boundary definition\n      - fieldname: riskAssessmentMethodology\n        description: Risk assessment approach for ISO 27001 compliance\n  scrs-form:\n    fields:\n      - fieldname: soc2TrustServiceCriteria\n        description: "Security, Availability, Processing Integrity, Confidentiality, Privacy"\n      - fieldname: soc2ReportType\n        description: Type I (point in time) or Type II (over period)\n      - fieldname: soc2AuditPeriod\n        description: Observation window for Type II audit\n  secerein-form:\n    fields:\n      - fieldname: pciDssLevel\n        description: PCI DSS compliance level based on transaction volume\n      - fieldname: hipaaRequirements\n        description: "PHI handling, BAA requirements if applicable"\n      - fieldname: industrySpecificCompliance\n        description: "FINRA, FDA 21 CFR Part 11, NERC CIP, etc.