cription: "Protocol, Format, Platform, Security, Performance, Availability"\n      - fieldname: constraintValue\n        description: Specific constraint value or requirement\n      - fieldname: constraintSource\n        description: "Source of the constraint — enterprise architecture, vendor, security"\n  ices-form:\n    fields:\n      - fieldname: impactedSystems\n        description: Systems affected by this constraint\n      - fieldname: impactedInterfaces\n        description: Specific interfaces affected\n      - fieldname: integrationPattern\n        description: "Integration patterns affected — sync, async, batch, event"\n  icem-form:\n    fields:\n      - fieldname: impactLevel\n        description: Impact on integration design.\n      - fieldname: designImplications\n        description: How this constraint affects integration design\n      - fieldname: workarounds\n        description: Potential workarounds or alternatives\n      - fieldname: mitigationApproach\n        description: How to work within this constraint\n  incoenco-form:\n    fields:\n      - fieldname: complianceRequired\n        description: Whether compliance is mandatory\n      - fieldname: validationMethod\n        description: How compliance is validated\n  trareq-tran-form:\n    fields:\n      - fieldname: i18nFramework\n        description: "flutter_localizations, intl, easy_localization"\n      - fieldname: stringExternalizationFormat\n        description: "ARB, JSON, YAML, Gettext"\n      - fieldname: localeHandling\n        description: How locales are loaded and switched\n  trrert-form:\n    fields:\n      - fieldname: rtlSupport\n        description: Whether right-to-left languages are supported\n      - fieldname: rtlImplementation\n        description: How RTL is implemented\n      - fieldname: bidirectionalText\n        description: Handling mixed LTR/RTL content\n      - fieldname: rtlMirroring\n        description: UI element mirroring rules\n  trrefo-form:\n    fields:\n  