les\n        description: Required firewall rule changes\n  expare-form:\n    fields:\n      - fieldname: sla\n        description: Partner system availability SLA\n      - fieldname: expectedLatency\n        description: Round-trip time expectations\n      - fieldname: expectedThroughput\n        description: Requests per second or data volume\n      - fieldname: timeoutPolicy\n        description: Connection and read timeout\n      - fieldname: retryStrategy\n        description: "Retry count, backoff policy"\n      - fieldname: circuitBreakerEnabled\n        description: Circuit breaker for partner failures\n  epdh-form:\n    fields:\n      - fieldname: dataClassification\n        description: Confidentiality level of exchanged data\n      - fieldname: encryptionRequirements\n        description: Encryption in transit and at rest\n      - fieldname: dataRetention\n        description: Retention of exchanged data\n  csis-form:\n    fields:\n      - fieldname: managedServices\n        description: "Databases, queues, caches, storage"\n      - fieldname: identityProvider\n        description: "Cognito, Azure AD, Auth0, Keycloak"\n      - fieldname: emailService\n        description: "SES, SendGrid, Mailgun"\n      - fieldname: notificationService\n        description: "Push notifications, SMS gateway"\n      - fieldname: storageService\n        description: "S3, Blob Storage, GCS"\n      - fieldname: cdnService\n        description: "CloudFront, Azure CDN, Cloudflare"\n      - fieldname: searchService\n        description: "Elasticsearch, OpenSearch, Algolia"\n  csin-form:\n    fields:\n      - fieldname: vpcPeering\n        description: VPC/VNet peering requirements\n      - fieldname: privateEndpoints\n        description: "Private link, service endpoints"\n      - fieldname: transitGateway\n        description: Cross-VPC or cross-region routing\n  csic-form:\n    fields:\n      - fieldname: dataResidency\n        description: Region restrictions for data storage\