escription: List of managed environments\n      - fieldname: environmentProvisioning\n        description: "Automated, on-demand, scheduled"\n      - fieldname: environmentCloning\n        description: Clone environment for testing\n      - fieldname: dataSeeding\n        description: Seed data for non-production envs\n      - fieldname: dataAnonymization\n        description: Anonymize production data for dev/test\n      - fieldname: dataSyncBetweenEnvs\n        description: Selective data promotion\n      - fieldname: environmentAccessControl\n        description: Who can access which environment\n      - fieldname: productionAccessPolicy\n        description: "Break-glass, approval workflow"\n      - fieldname: environmentVariableManagement\n        description: Per-env variable sets\n      - fieldname: notes\n        description: Additional environment management notes\n  sdtt-form:\n    fields:\n      - fieldname: requestTracing\n        description: End-to-end request trace viewer\n      - fieldname: slowQueryAnalysis\n        description: Identify slow database queries\n      - fieldname: dependencyMapping\n        description: Visualize service dependencies\n  sdtl-form:\n    fields:\n      - fieldname: logAggregation\n        description: "ELK, Loki, CloudWatch Logs"\n      - fieldname: logSearchCapability\n        description: Full-text search across logs\n      - fieldname: correlatedLogView\n        description: View logs across services by trace ID\n  sdtss-form:\n    fields:\n      - fieldname: adminDiagnosticEndpoints\n        description: "/info, /env, /metrics endpoints"\n      - fieldname: databaseQueryConsole\n        description: Read-only query interface for admins\n      - fieldname: notes\n        description: Additional diagnostic tool notes\n  monito-moni-form:\n    fields:\n      - fieldname: monitoringStrategy\n        description: "Proactive, reactive, hybrid approach"\n      - fieldname: observabilityMaturity\n        description: Curren