tent"\n      - fieldname: fullPageErrorTemplate\n        description: "Design for full-page errors (500, 503)"\n  sedc-form:\n    fields:\n      - fieldname: showTechnicalDetails\n        description: "Display error codes, request IDs"\n      - fieldname: showRetryOption\n        description: Offer a retry button on the error\n      - fieldname: showContactSupport\n        description: Show a link to contact support\n      - fieldname: showStatusPageLink\n        description: Show a link to the service status page\n      - fieldname: offlineModeMessage\n        description: Message when app detects offline state\n  sedf-form:\n    fields:\n      - fieldname: cachedDataFallback\n        description: Show stale data with indicator\n      - fieldname: retryStrategy\n        description: Automatic retry with backoff\n      - fieldname: maxRetryAttempts\n        description: Number of retries before giving up\n      - fieldname: retryDelaySeconds\n        description: Seconds to wait between retries\n  seceh-form:\n    fields:\n      - fieldname: technicalDescription\n        description: Developer-facing description\n      - fieldname: suggestedAction\n        description: What user should do\n      - fieldname: retryable\n        description: Whether retry is likely to help\n      - fieldname: autoRetry\n        description: System automatically retries\n      - fieldname: displayMethod\n        description: How this error is displayed\n  seceo-form:\n    fields:\n      - fieldname: notifySupport\n        description: Auto-notify support team\n      - fieldname: logLevel\n        description: "Error, warning, info"\n  erre-reco-form:\n    fields:\n      - fieldname: formDataPreservation\n        description: How unsaved form data is preserved on error\n      - fieldname: sessionRecovery\n        description: How expired sessions are handled\n      - fieldname: supportContactMethod\n        description: "Chat, email, phone, ticket"\n  erdp-form:\n    fields:\n      - fi