ait / Landscape / Auto"\n  rela-form:\n    fields:\n      - fieldname: marginTop\n        description: Override top margin\n      - fieldname: marginBottom\n        description: Override bottom margin\n      - fieldname: marginLeft\n        description: Override left margin\n      - fieldname: marginRight\n        description: Override right margin\n  rehefo-form:\n    fields:\n      - fieldname: headerTemplate\n        description: "Page header override, e.g. {logo} {reportTitle}"\n      - fieldname: footerTemplate\n        description: Page footer override\n      - fieldname: coverPage\n        description: Yes / No — include a cover page\n      - fieldname: coverPageTemplate\n        description: Cover page content template\n      - fieldname: tableOfContents\n        description: Yes / No — include TOC for multi-section reports\n  regr-form:\n    fields:\n      - fieldname: defaultSortField\n        description: Default sort column or field\n      - fieldname: defaultSortDirection\n        description: Ascending / Descending\n      - fieldname: defaultGroupBy\n        description: Default grouping field\n      - fieldname: groupSummary\n        description: Yes / No — show subtotals per group\n      - fieldname: grandTotal\n        description: Yes / No — show grand total row\n  rf-form:\n    fields:\n      - fieldname: conditionalFormatting\n        description: Description of conditional formatting rules\n      - fieldname: highlightRules\n        description: "Row/cell highlight rules, e.g. overdue items in red"\n  rein-form:\n    fields:\n      - fieldname: drillDownTarget\n        description: Report or screen navigated to on row click\n      - fieldname: drillThroughReports\n        description: "Reports reachable from this report — report section ids (REPENT-REPO-…), comma-separated"\n      - fieldname: parameterForm\n        description: Description of user input form shown before generation\n      - fieldname: emptyDataMessage\n        description: Message to display when report has no data\n  repa-form:\n    fields:\n      - fieldname: maxRows\n        description: Row limit for performance; 0 = unlimited\n      - fieldname: paginationStyle\n        description: Page-break / Continuous / Scrollable\n      - fieldname: rowsPerPage\n        description: For paginated tabular reports\n  rese-form:\n    fields:\n      - fieldname: localization\n        description: "Locales supported, e.g. de-DE, en-US, fr-FR"\n      - fieldname: brandingOverride\n        description: Override branding for this report\n      - fieldname: dataLevelSecurity\n        description: Row/column level security rules narrowing what the report shows a caller who is already permitted to generate it\n  reli-form:\n    fields:\n      - fieldname: archiveRetention\n        description: "Retention policy for generated instances, e.g. 90 days"\n      - fieldname: signatureRequired\n        description: Yes / No — does the report require a digital signature\n      - fieldname: approvalWorkflow\n        description: "Approval steps before distribution, if any"\n      - fieldname: notes\n        description: Additional design notes or open questions\n  reseda-form:\n    fields:\n      - fieldname: purpose\n        description: What this section communicates\n      - fieldname: dataSource\n        description: Data source or query for this section\n      - fieldname: dataScope\n        description: Scope filter applied to the section data\n      - fieldname: textContent\n        description: Static text or template for text-type sections\n      - fieldname: notes\n        description: Design notes\n  resela-form:\n    fields:\n      - fieldname: displayOrder\n        description: Position within the report\n      - fieldname: pageBreakBefore\n        description: Yes / No — force page break before this section\n      - fieldname: pageBreakAfter\n        description: Yes / No — force page break after this section\n      - fieldname: repeatOnNewPage\n    