ields:\n      - fieldname: borderStyle\n        description: "Solid, dashed, none"\n      - fieldname: cornerRadius\n        description: Rounding of component corners\n      - fieldname: elevation\n        description: Depth or z-level of the surface\n      - fieldname: shadowStyle\n        description: Drop shadow appearance\n  uicom-inte-form:\n    fields:\n      - fieldname: tapBehavior\n        description: What happens on tap/click\n      - fieldname: longPressBehavior\n        description: What happens on long press\n      - fieldname: doubleTapBehavior\n        description: What happens on double tap\n      - fieldname: swipeBehavior\n        description: What happens on swipe gestures\n      - fieldname: dragBehavior\n        description: What happens on drag gestures\n      - fieldname: hoverBehavior\n  uceib-form:\n    fields:\n      - fieldname: focusBehavior\n        description: "Focus ring, highlight, navigation"\n      - fieldname: keyboardNavigation\n        description: "Tab order, arrow key behavior"\n      - fieldname: keyboardShortcuts\n        description: Key combinations the component handles\n  ucea-form:\n    fields:\n      - fieldname: entryAnimation\n        description: How the component appears\n      - fieldname: exitAnimation\n        description: How the component disappears\n      - fieldname: stateTransitions\n        description: Animation between states\n      - fieldname: feedbackAnimations\n        description: "Ripple, scale, color change"\n  uicoensc-form:\n    fields:\n      - fieldname: scrollBehavior\n        description: If component is scrollable\n      - fieldname: stickyBehavior\n        description: "Headers, columns that stick"\n  uicom-resp-form:\n    fields:\n      - fieldname: mobileLayout\n        description: Layout on mobile (< 600dp)\n      - fieldname: tabletLayout\n        description: Layout on tablet (600-1024dp)\n      - fieldname: desktopLayout\n        description: "Layout on desktop (> 1024dp)"\n      - fieldname: breakpointBehavior\n        description: What changes at breakpoints\n      - fieldname: adaptiveContent\n        description: Content that appears/hides\n      - fieldname: touchTargets\n        description: Minimum touch target sizes\n      - fieldname: orientationBehavior\n        description: Portrait vs. landscape\n  uicom-acce-form:\n    fields:\n      - fieldname: semanticRole\n        description: ARIA role or semantic meaning\n      - fieldname: screenReaderLabel\n        description: How screen readers announce\n      - fieldname: screenReaderHint\n        description: Additional context for screen readers\n      - fieldname: focusOrder\n        description: Tab order in context\n      - fieldname: ariaAttributes\n        description: Required ARIA attributes\n      - fieldname: colorContrastNotes\n        description: Contrast ratios and compliance notes\n      - fieldname: motionSensitivity\n        description: Reduced motion behavior\n      - fieldname: textScalingBehavior\n        description: How component responds to text scaling\n  uicom-auth-form:\n    fields:\n      - fieldname: authBasePath\n        description: Base path for authorization lookup\n      - fieldname: authVisibilityBehavior\n        description: "Hidden, visible, conditionally visible"\n      - fieldname: authEnabledBehavior\n        description: "Disabled, enabled, conditionally enabled"\n      - fieldname: authReadonlyBehavior\n        description: Readonly state behavior\n      - fieldname: authActionControl\n        description: Which actions are auth-controlled\n      - fieldname: authFallbackBehavior\n        description: Behavior when auth unavailable\n      - fieldname: fourStateMapping\n        description: Mapping to TomAuthState four states\n  uicom-reso-form:\n    fields:\n      - fieldname: resourceBasePath\n        description: Base path for resource lookup\n      - fieldname: labelResource\n        description: Message key (MSGKR registry) for label text\n      - fieldname: hintResource\n        description: Message key (MSGKR registry) for hint text\n      - fieldname: errorResource\n        description: Message key (MSGKR registry) for error messages\n      - fieldname: tooltipResource\n        description: Message key (MSGKR registry) for tooltip text\n      - fieldname: placeholderResource\n        description: Message key (MSGKR registry) for placeholder text\n      - fieldname: ariaLabelResource\n        description: Message key (MSGKR registry) for the ARIA label\n      - fieldname: iconResource\n        description: Resource key for icon selection\n      - fieldname: resourceFallbacks\n        description: Fallback behavior when resource missing\n  uicom-data-form:\n    fields:\n      - fieldname: dataType\n        description: Type of data component displays/edits\n      - fieldname: bindingPattern\n        description: "Observable, form field, direct"\n      - fieldname: valueAccessor\n        description: How value is read/written\n      - fieldname: changeNotification\n        description: How changes are communicated\n      - fieldname: validationIntegration\n        description: How validation errors are displayed\n      - fieldname: dirtyTracking\n        description: How dirty state is tracked\n      - fieldname: undoRedoSupport\n        description: Whether edits can be undone and redone\n  csev-form:\n    fields:\n      - fieldname: visualChanges\n        description: How appearance changes in this state\n      - fieldname: colorOverrides\n        description: Colors replaced in this state\n      - fieldname: opacityChange\n        description: Opacity applied in this state\n      - fieldname: iconChange\n        description: Icon swapped in this state\n      - fieldname: textChange\n        description: Label or text shown in this state\n  cseb-form:\n    fields:\n      - fieldname: interactionChanges\n        description: How interactions change\n      - fieldname: accessibilityState\n        description: Screen reader announcements\n  cset-form:\n    fields:\n      - fieldname: entryTrigger\n        description: What causes entry to this state\n      - fieldname: exitTrigger\n        description: What causes exit from this state\n      - fieldname: transitionAnimation\n        description: Animation played during the transition\n  cvev-form:\n    fields:\n      - fieldname: colorSchemeVariant\n        description: Color palette applied to this variant\n      - fieldname: borderVariant\n        description: Border style for this variant\n      - fieldname: elevationVariant\n        description: Shadow or elevation level\n  cveb-form:\n    fields:\n      - fieldname: behaviorDifferences\n        description: How behavior differs from the base component\n      - fieldname: useCaseDifferences\n        description: When to use this variant\n      - fieldname: implementationNote\n        description: How variant is implemented\n      - fieldname: libraryVariant\n        description: "Corresponding variant in the shared component library, if one exists"\n  caeg-form:\n    fields:\n      - fieldname: actionResult\n        description: Expected outcome\n      - fieldname: authRequired\n        description: Requires authorization\n      - fieldname: authPermission\n        description: Required permission\n      - fieldname: confirmationRequired\n        description: Whether a confirmation prompt is shown\n      - fieldname: confirmationMessage\n        description: Text shown in the confirmation prompt\n  caee-form:\n    fields:\n      - fieldname: asyncBehavior\n        description: Loading state during async\n      - fieldname: errorHandling\n        description: What happens when the action fails\n      - fieldname: successFeedback\n        description: Confirmation shown on success\n  lacose-lang-form:\n    fields:\n      - fieldname: pickerLocation\n        description: "Header, footer, settings, onboarding"\n      - fieldname: pickerStyle\n        description: "Dropdown, modal, full page"\n      - fieldname: languageDisplay\n        description: "Native names, English names, flags"\n      - fieldname: countryDisplay\n        description: How countries are displayed\n      - fieldname: searchable\n        description: Can user search languages/countries\n  lcsd-form:\n    fields:\n      - fieldname: defaultLanguage\n        description: How default language is determined\n      - fieldname: defaultCountry\n        description: How default country is determined\n      - fieldname: autoDetection\n        description: "Browser, OS, geo-IP detection"\n  lcsp-form:\n    fields:\n      - fieldname: guestRetention\n        description: Whether and for how long a preference chosen before sign-in is retained\n      - fieldname: signInCarryOver\n        description: What happens to a guest-chosen locale when the user signs in and a stored preference applies\n      - fieldname: reselectionPrompt\n        description: When the user is asked to confirm or re-pick the retained preference\n  lcsf-form:\n    fields:\n      - fieldname: localeFallbackBehavior\n        description: What happens when locale unavailable\n      - fieldname: partialLocalSupport\n        description: "UI in one locale, content in another"\n      - fieldname: missingTranslationDisplay\n        description: How missing translations are shown\n  lcsu-form:\n    fields:\n      - fieldname: languageSwitchBehavior\n        description: "Page reload, inline update"\n      - fieldname: confirmationRequired\n        description: Confirm before switching\n      - fieldname: contentRetention\n        description: What happens to in-progress content\n  protot-prot-form:\n    fields:\n      - fieldname: prototypePurpose\n        description: "Primary goal: validation, alignment, feasibility"\n      - fieldname: prototypeScope\n        description: What is included in prototype\n      - fieldname: targetAudience\n        description: Who will evaluate the prototype\n      - fieldname: successCriteria\n        description: How success is measured\n  prti-form:\n    fields:\n      - fieldname: prototypeTimeline\n        description: Duration for prototype phase\n      - fieldname: prototypeDeadline\n        description: When prototype must be ready\n      - fieldname: evaluationPeriod\n        description: How long for evaluation\n  prores-form:\n    fields:\n      - fieldname: prototypeTeam\n        description: Who builds the prototype\n      - fieldname: prototypeBudget\n        description: Budget allocation\n      - fieldname: prototypeEnvironment\n        description: Where prototype is deployed\n  prgo-form:\n    fields:\n      - fieldname: acceptanceCriteria\n        description: Required criteria to proceed\n      - fieldname: stakeholderSignoff\n        description: Who must approve prototype\n  pg-goal-form:\n    fields:\n      - fieldname: usabilityValidation\n        description: Validate usability of key workflows\n      - fieldname: stakeholderAlignment\n        description: Align stakeholders on UI/UX\n      - fieldname: technicalFeasibility\n        description: Prove technical approach works\n      - fieldname: performanceValidation\n        description: Validate performance targets\n      - fieldname: integrationValidation\n        description: Validate third-party integrations\n  prgori-form:\n    fields:\n      - fieldname: riskMitigation\n        description: Risks the prototype addresses\n      - fieldname: unknownsResolution\n        description: Unknowns to be resolved\n      - fieldname: assumptionsTesting\n        description: Assumptions to be tested\n  prgofe-form:\n    fields:\n      - fieldname: userFeedbackGoals\n        description: What feedback to gather\n      - fieldname: usabilityTestingPlan\n        description: How usability testing is done\n      - fieldname: feedbackIntegration\n        description: How feedback flows back\n  prfesu-feat-form:\n    fields:\n      - fieldname: selectionCriteria\n        description: How features were selected\n      - fieldname: riskBasedSelection\n        description: High-risk features included\n      - fieldname: valueBasedSelection\n        description: High-value features included\n      - fieldname: uncertaintyBasedSelection\n        description: Most uncertain features included\n  pfss-form:\n    fields:\n      - fieldname: includedFeatures\n        description: Features in prototype\n      - fieldname: excludedFeatures\n        description: Features not in prototype\n      - fieldname: partialFeatures\n        description: Features partially implemented\n  pfsf-form:\n    fields:\n      - fieldname: prototypeFidelity\n        description: Qualitative fidelity band of the prototype.\n      - fieldname: interactiveFidelity\n        description: Level of interactivity\n      - fieldname: dataFidelity\n        description: Real vs. mock data\n      - fieldname: visualFidelity\n        description: Production visuals vs. wireframes\n  prtyse-prot-form:\n    fields:\n      - fieldname: prototypeType\n        required: true\n        description: "Reusable, Training, Throwaway"\n      - fieldname: typeRationale\n        description: Why this type was chosen\n      - fieldname: typeImplications\n        description: Implications for development\n      - fieldname: codeQualityExpectation\n        description: "Production, demo, quick-and-dirty"\n      - fieldname: documentationRequirement\n        description: Documentation needed\n      - fieldname: transitionPlan\n        description: How prototype transitions\n  reupro-reus-form:\n    fields:\n      - fieldname: codeQualityRequirements\n        description: Standards prototype code must meet\n      - fieldname: testCoverageRequirement\n        description: Required test coverage\n      - fieldname: codeReviewRequired\n        description: Whether code review is required\n      - fieldname: documentationRequired\n        description: Whether documentation is required\n  reprar-form:\n    fields:\n      - fieldname: architectureAlignment\n        description: How prototype aligns with target architecture\n      - fieldname: refactoringPlan\n        description: Planned refactoring after prototype\n      - fieldname: technicalDebt\n        description: Acceptable technical debt\n  reprin-form:\n    fields:\n      - fieldname: integrationPlan\n        description: How prototype integrates into product\n      - fieldname: featureBranchStrategy\n        description: Git branching approach\n      - fieldname: mergeCriteria\n        description: Criteria to merge prototype code\n  reprtr-form:\n    fields:\n      - fieldname: transitionTimeline\n        description: When the transition to the product occurs\n      - fieldname: teamHandoff\n        description: Handoff to development team\n  tp-trai-form:\n    fields:\n      - fieldname: designDecisionsCarriedForward\n        description: What design decisions are preserved\n      - fieldname: patternsDocumented\n        description: Patterns documented from prototype\n      - fieldname: lessonsLearned\n        description: What was learned\n  trprdi-form:\n    fields:\n      - fieldname: codeDisposition\n        description: What happens to prototype code\n      - fieldname: reimplementationPlan\n        description: Plan for reimplementing features\n      - fieldname: reimplementationEstimate\n        description: Effort to reimplement\n  trprou-form:\n    fields:\n      - fieldname: documentationProduced\n        description: Documentation from prototype\n      - fieldname: designSystemOutput\n        description: Design system artifacts\n      - fieldname: componentSpecifications\n        description: Component specs from prototype\n      - fieldname: teamSkillsGained\n        description: Skills team gained\n      - fieldname: technologyInsights\n        description: Technology insights gained\n  thpr-thro-form:\n    fields:\n      - fieldname: evaluationCriteria\n        description: Criteria for evaluation\n      - fieldname: evaluationMethod\n        description: How prototype is evaluated\n      - fieldname: evaluationParticipants\n        description: Who participates in evaluation\n      - fieldname: evaluationTimeline\n        description: When evaluation takes place\n  thprfi-form:\n    fields:\n      - fieldname: findingsDocumentation\n        description: How findings are documented\n      - fieldname: recommendationsOutput\n        description: Recommendations produced\n      - fieldname: decisionsMade\n        description: Decisions made based on prototype\n  thprdi-form:\n    fields:\n      - fieldname: disposalPlan\n        description: How prototype is disposed\n      - fieldname: archivingApproach\n        description: Whether/how prototype is archived\n      - fieldname: nextSteps\n        description: What happens after evaluation\n  thprva-form:\n    fields:\n      - fieldname: insightsCaptured\n        description: Key insights from prototype\n      - fieldname: futureReference\n        description: What to preserve for future\ndocument:\n  sections:\n    dochd:\n      section-type: dochd\n      optional: true\n    deviz:\n      section-type: deviz\n      optional: true\n    scrdz:\n      section-type: scrdz\n      optional: true\n    scflst:\n      section-type: scflst\n      optional: true\n    prla:\n      section-type: prla\n      optional: true\n    redf:\n      section-type: redf\n      optional: true\n    erhaco:\n      section-type: erhaco\n      optional: true\n    usas:\n      section-type: usas\n      optional: true\n    access:\n      section-type: access\n      optional: true\n    rede:\n      section-type: rede\n      optional: true\n    uico:\n      section-type: uico\n      optional: true\n    lacose:\n      section-type: lacose\n      optional: true\n    protot:\n      section-type: protot\n      optional: true\n    wianmo:\n      section-type: wianmo\n      optional: true\n',
  'information-model': '# Generated from the TomSpecs object model — do not edit.\n# Schema: information-model/1.3\n\ntitle-format: "# <!--[IFM]--> Information Model"\nsection-types:\n  biobat-attr-lst:\n    prefix: BIOBAT_ATTR_LST\n    subsection-types:\n      biobat-attr:\n        max-count: infinite\n    min-text-length: 0\n    max-text-length: 0\n    description: Add one entry per business object attribute.\n  birure-keyb-lst:\n    prefix: BIRURE_KEYB_LST\n    subsection-types:\n      birure-keyb:\n        max-count: infinite\n    min-text-length: 0\n    max-text-length: 0\n    description: Add one entry per business rule reference.\n  birure-rule-ref:\n    prefix: BIRURE_RULE_REF\n    description: The resolved link to the business rule this entry cites.\n  rulexm-exam-lst:\n    prefix: RULEXM_EXAM_LST\n    subsection-types:\n      rulexm-exam:\n        max-count: infinite\n    min-text-length: 0\n    max-text-length: 0\n    description: Add one entry per rule example.\n  acrse-acce-lst:\n    prefix: ACRSE_ACCE_LST\n    subsection-types:\n      acrse-acce:\n        max-count: infinite\n    min-text-length: 0\n    max-text-length: 0\n    description: Add one entry per access restriction.\n  azlvl-leve-lst:\n    prefix: AZLVL_LEVE_LST\n    subsection-types:\n      azlvl-leve:\n        max-count: infinite\n        min-count: 1\n    min-text-length: 0\n    max-text-length: 0\n    description: Add one entry per access state that has its own requirement. At least Full must be authored; Read and Disabled inherit downwards when omitted.\n  behav-beha-lst:\n    prefix: BEHAV_BEHA_LST\n    subsection-types:\n      behav-beha:\n        max-count: infinite\n    min-text-length: 0\n    max-text-length: 0\n    description: Add one entry per behavior rule.\n  bjoen-obje-lst:\n    prefix: BJOEN_OBJE_LST\n    subsection-types:\n      bjoen-obje:\n        max-count: infinite\n        min-count: 1\n    min-text-length: 0\n    max-text-length: 0\n    description: Business object catalog (list).\n  daatt-attr-lst:\n    prefix: DAATT_ATTR_LST\n    subsection-types:\n      daatt-attr:\n        max-count: infinite\n    min-text-length: 0\n    max-text-length: 0\n    description: Add one entry per data attribute.\n  daent-enti-lst:\n    prefix: DAENT_ENTI_LST\n    subsection-types:\n      daent-enti:\n        max-count: infinite\n        min-count: 1\n    min-text-length: 0\n    max-text-length: 0\n    description: Entity inventory (list).\n  dataa-cons-lst:\n    prefix: DATAA_CONS_LST\n    subsection-types:\n      dataa-cons:\n        max-count: infinite\n    min-text-length: 0\n    max-text-length: 0\n    description: Add one entry per attribute constraint.\n  dclse-item-lst:\n    prefix: DCLSE_ITEM_LST\n    subsection-types:\n      dclse-item:\n        max-count: infinite\n    min-text-length: 0\n    max-text-length: 0\n    description: Add one entry per data classification level.\n  displ-disp-lst:\n    prefix: DISPL_DISP_LST\n    subsection-types:\n      displ-disp:\n        max-count: infinite\n    min-text-length: 0\n    max-text-length: 0\n    description: Add one entry per display property.\n  dmene-enum-lst:\n    prefix: DMENE_ENUM_LST\n    subsection-types:\n      dmene-enum:\n        max-count: infinite\n    min-text-length: 0\n    max-text-length: 0\n    description: Add one entry per domain enum (closed value set).\n  dmeva-valu-lst:\n    prefix: DMEVA_VALU_LST\n    subsection-types:\n      dmeva-valu:\n        max-count: infinite\n        min-count: 1\n    min-text-length: 0\n    max-text-length: 0\n    description: Add one entry per enum value.\n  encns-cons-lst:\n    prefix: ENCNS_CONS_LST\n    subsection-types:\n      encns-cons:\n        max-count: infinite\n    min-text-length: 0\n    max-text-length: 0\n    description: Add one entry per entity constraint.\n  enidx-inde-lst:\n    prefix: ENIDX_INDE_LST\n    subsection-types:\n      enidx-inde:\n        max-count: infinite\n    min-text-length: 0\n    max-text-length: 0\n    de