ements.\n  sopg:\n    prefix: SOPG\n    format: sopg-form\n    description: Signatory and quorum governance.\n  sopt:\n    prefix: SOPT\n    format: sopt-form\n    description: Review timeline.\n  test:\n    prefix: TEST\n    description: Test strategy (new in Phase A).\n  tspe:\n    prefix: TSPE\n    format: tspe-form\n    description: Post-execution.\n  uacr:\n    prefix: UACR\n    format: uacr-form\n    description: "Entry, exit, and suspension criteria."\n  uaen:\n    prefix: UAEN\n    format: uaen-form\n    description: Environment.\n  uago:\n    prefix: UAGO\n    format: uago-form\n    description: Participants and governance.\n  uare:\n    prefix: UARE\n    format: uare-form\n    description: Reporting.\n  uasc:\n    prefix: UASC\n    format: uasc-form\n    description: Scope and objectives.\n  uatr:\n    prefix: UATR\n    format: uatr-form\n    description: Training and readiness.\n  waco:\n    prefix: WACO\n    format: waco-form\n    description: Scope of coverage.\n  wadu:\n    prefix: WADU\n    format: wadu-form\n    description: Duration and activation.\n  wafi:\n    prefix: WAFI\n    format: wafi-form\n    description: Financial terms.\n  wapr:\n    prefix: WAPR\n    format: wapr-form\n    description: Process for defect handling.\n  wate:\n    prefix: WATE\n    subsection-types:\n      wadu:\n        max-count: 1\n      waco:\n        max-count: 1\n      wasele-serv-lst:\n        max-count: 1\n      wapr:\n        max-count: 1\n      watr:\n        max-count: 1\n      wafi:\n        max-count: 1\n    description: Warranty terms.\n  watr:\n    prefix: WATR\n    format: watr-form\n    description: Transition to support.\nform-types:\n  qlfwk-fram-form:\n    fields:\n      - fieldname: qualityModel\n        description: "ISO 25010, McCall, Boehm, custom"\n      - fieldname: qualityModelVersion\n        description: Specific version of quality model\n      - fieldname: qualityModelAdaptations\n        description: How standard model is adapted for this project\n  qfobj-form:\n    fields:\n      - fieldname: objectivesHierarchy\n        description: How quality objectives are structured\n      - fieldname: objectivesAlignment\n        description: How quality objectives align with business goals\n      - fieldname: objectivesMeasurability\n        description: "All objectives SMART, key objectives only"\n  qftrd-form:\n    fields:\n      - fieldname: primaryQualityAttribute\n        description: Most important attribute when trade-offs required\n      - fieldname: secondaryQualityAttribute\n        description: Attribute yielded when the primary attribute takes precedence\n      - fieldname: tradeOffApproach\n        description: How conflicts between attributes are resolved\n      - fieldname: qualityCompromiseAuthority\n        description: Who can authorize quality trade-offs\n  qfver-form:\n    fields:\n      - fieldname: verificationStrategy\n        description: "Testing, review, analysis, demonstration"\n      - fieldname: verificationCoverage\n        description: "All attributes, critical only, risk-based"\n      - fieldname: defectClassification\n        description: "Critical, major, minor, trivial"\n      - fieldname: defectPriorityScheme\n        description: "P1-P5, urgent/high/medium/low"\n  qcadf-form:\n    fields:\n      - fieldname: categoryDescription\n        description: Purpose and scope of this category\n      - fieldname: categoryScope\n        description: What aspects of quality this covers\n      - fieldname: categoryPriority\n        description: Qualitative priority band.\n      - fieldname: categoryRationale\n        description: Why this priority level\n  qcarl-form:\n    fields:\n      - fieldname: parentCategory\n        description: Higher-level category if hierarchical\n      - fieldname: relatedCategories\n        description: Categories that interact with this one\n      - fieldname: conflictingCategories\n        description: Categories that may trade off against this\n  qcagv-form:\n    fields:\n      - fieldname: categoryOwner\n        description: Role responsible for this quality area\n      - fieldname: reviewFrequency\n        description: How often category metrics are reviewed\n      - fieldname: escalationThreshold\n        description: When category issues escalate\n  qcamt-form:\n    fields:\n      - fieldname: primaryMetric\n        description: Main metric for this category\n      - fieldname: secondaryMetrics\n        description: Supporting metrics\n      - fieldname: targetValue\n        description: Target for primary metric\n      - fieldname: currentBaseline\n        description: Starting baseline value\n  fnsu-func-form:\n    fields:\n      - fieldname: functionalSuitabilityApproach\n        description: How functional completeness and correctness are assured\n      - fieldname: functionalCoverageTarget\n        description: Required vs. optional feature coverage\n      - fieldname: correctnessStandard\n        description: "Acceptable defect density, accuracy thresholds"\n  coquin-form:\n    fields:\n      - fieldname: dataIntegrityRequirement\n        description: "ACID, eventual consistency"\n      - fieldname: dataValidationCoverage\n        description: "All inputs, critical inputs"\n      - fieldname: dataCorruptionHandling\n        description: "Detection, recovery, prevention"\n  coquac-form:\n    fields:\n      - fieldname: calculationAccuracyTarget\n        description: "Decimal precision, rounding rules"\n      - fieldname: financialAccuracyRequirement\n        description: "Penny-accurate, significant figures"\n      - fieldname: auditTrailRequirement\n        description: "All changes, financial only"\n  coquve-form:\n    fields:\n      - fieldname: correctnessVerification\n        description: "Unit tests, integration tests, UAT"\n      - fieldname: testCoverageTarget\n        description: "Code coverage %, requirement coverage"\n      - fieldname: regressionTestingApproach\n        description: "Automated, manual, risk-based"\n  peef-perf-form:\n    fields:\n      - fieldname: technicalQualityPhilosophy\n        description: "Performance-first, maintainability-first, balanced"\n      - fieldname: architecturalQualityGoals\n        description: Key architectural quality attributes\n      - fieldname: technicalDebtTolerance\n        description: "Zero, controlled, pragmatic"\n      - fieldname: codeQualityStandard\n        description: "Style guide, linting rules"\n      - fieldname: designPrinciplesAdherence\n        description: "SOLID, DRY, KISS, YAGNI"\n  efquth-form:\n    fields:\n      - fieldname: throughputTarget\n        description: "Requests/second, transactions/minute"\n      - fieldname: concurrentUsersTarget\n        description: Peak concurrent users supported\n      - fieldname: scalabilityModel\n        description: "Horizontal, vertical, auto-scaling"\n  efqure-form:\n    fields:\n      - fieldname: cpuUtilizationLimit\n        description: "Max sustained CPU usage (e.g., <70%)"\n      - fieldname: memoryUtilizationLimit\n        description: Max memory usage\n      - fieldname: storageEfficiencyTarget\n        description: Data storage per user/record\n      - fieldname: networkBandwidthLimit\n        description: Max bandwidth consumption\n  efquve-form:\n    fields:\n      - fieldname: loadTestingRequirement\n        description: "Load test scenarios, thresholds"\n      - fieldname: performanceProfilingApproach\n        description: "APM tools, custom instrumentation"\n      - fieldname: performanceBaselineDate\n        description: When baseline was established\n      - fieldname: performanceSlaDefinition\n        description: SLA for performance metrics\n  cmpt-comp-form:\n    fields:\n      - fieldname: coExistenceRequirements\n        description: Other products sharing the environment without adverse impact\n      - fieldname: interoperabilityStandards\n        description: Protocols/formats for exchanging and using information\n  incp-inte-form:\n    fields:\n      - fieldname: userQualityPhilosophy\n        description: "User-first, balanced, efficiency-focused"\n      - fieldname: targetUserExperience\n        description: "Delightful, efficient, adequate, minimal"\n      - fieldname: userResearchBasis\n        description: "Personas, surveys, interviews, analytics"\n      - fieldname: userFeedbackChannel\n        description: How user quality feedback is collected\n      - fieldname: userSatisfactionTarget\n        description: "NPS > 50, CSAT > 80%, etc."\n      - fieldname: accessibilityLevel\n        description: "WCAG 2.1 AA, AAA, Section 508"\n  usaop-form:\n    fields:\n      - fieldname: operabilityMetric\n        description: "Task completion rate, error rate"\n      - fieldname: operabilityVerification\n        description: "Usability testing, heuristic evaluation"\n      - fieldname: ergonomicsTarget\n        description: "Reduce cognitive load, minimize clicks"\n  usaln-form:\n    fields:\n      - fieldname: learnabilityVerification\n        description: "First-use testing, training time measurement"\n      - fieldname: onboardingRequirement\n        description: "Self-service, guided tour, training required"\n  usacl-form:\n    fields:\n      - fieldname: functionalClarityTarget\n        description: "Labels, icons, workflows self-explanatory"\n      - fieldname: helpSystemRequirement\n        description: "Contextual help, tooltips, documentation"\n      - fieldname: complexityLimit\n        description: "Max steps per workflow, max form fields"\n      - fieldname: cognitiveLoadTarget\n        description: "Info per screen, decision points"\n  usain-form:\n    fields:\n      - fieldname: undoRequirement\n        description: "All actions, critical actions, none"\n      - fieldname: customizationLevel\n        description: "User preferences, layout, workflow"\n  usapr-form:\n    fields:\n      - fieldname: responseTimeP50\n        description: "Median response time target (e.g., <200ms)"\n