efix: TMER\n    format: tmer-form\n    description: Recognition activities.\n  tmes:\n    prefix: TMES\n    format: tmes-form\n    description: Current status.\n  tomc:\n    prefix: TOMC\n    subsection-types:\n      oapc:\n        max-count: 1\n      psaai:\n        max-count: 1\n    description: SBP.7 Target Operating Model concept. Seeds → TOM.\n  tpai:\n    prefix: TPAI\n    subsection-types:\n      tpaia:\n        max-count: 1\n      tpaic:\n        max-count: 1\n      tpail:\n        max-count: 1\n      tpaim:\n        max-count: 1\n      thpaapinai:\n        max-count: 1\n      tpaio:\n        max-count: 1\n    description: Third-party API integrations.\n  tpps:\n    prefix: TPPS\n    format: tpps-form\n    description: "Aggregate the technical pain points into category metrics: technical-debt estimate, security-vulnerability counts, systems at end of life, vendor lock-in risk, and integration complexity."\n  tras:\n    prefix: TRAS\n    subsection-types:\n      trasef:\n        max-count: 1\n      trasim:\n        max-count: 1\n      trasre:\n        max-count: 1\n    description: Assessment and evaluation.\n  trca:\n    prefix: TRCA\n    subsection-types:\n      trcaru:\n        max-count: 1\n      trcaac:\n        max-count: 1\n      trcaco:\n        max-count: 1\n    description: Troubleshooting capabilities.\n  trcs:\n    prefix: TRCS\n    format: trcs-form\n    description: Cipher suite policy.\n  trcv:\n    prefix: TRCV\n    format: trcv-form\n    description: Certificate validation rules.\n  trea:\n    prefix: TREA\n    format: trea-form\n    description: Risk assessment and exposure details.\n  trec:\n    prefix: TREC\n    format: trec-form\n    description: Assumptions and constraints.\n  tred:\n    prefix: TRED\n    format: tred-form\n    description: "Requirement details: description, category, priority."\n  trei:\n    prefix: TREI\n    format: trei-form\n    description: Impact assessment.\n  trem:\n    prefix: TREM\n    format: trem-form\n    de