ssional licenses needed\n      - fieldname: languageRequirements\n        description: Languages the role requires\n      - fieldname: travelRequirements\n        description: Expected travel frequency and destinations\n  nrqs-form:\n    fields:\n      - fieldname: physicalRequirements\n        description: "Physical demands of the role, if any"\n      - fieldname: backgroundCheck\n        description: Type of background check required\n      - fieldname: securityClearance\n        description: "Security clearance level needed, if any"\n  nrsa-form:\n    fields:\n      - fieldname: primarySystems\n        description: Main applications used every day\n      - fieldname: secondarySystems\n        description: Applications used occasionally\n      - fieldname: dataAccess\n        description: Data domains the role may access\n      - fieldname: securityRole\n        description: Role assigned in the access control system\n      - fieldname: privilegedAccess\n        description: Any admin or elevated rights required\n      - fieldname: mobileAccess\n        description: Mobile app or device requirements\n      - fieldname: remoteAccessTools\n        description: Remote access such as VPN or virtual desktop\n      - fieldname: communicationTools\n        description: "Email, chat and video tools needed"\n      - fieldname: reportingTools\n        description: "BI, dashboard or analytics tools needed"\n      - fieldname: accessProvisioning\n        description: How and when access is provisioned\n  nerope-form:\n    fields:\n      - fieldname: performanceObjectives\n        description: Key goals the role is expected to achieve\n      - fieldname: kpis\n        description: Quantitative metrics used to gauge success\n      - fieldname: qualitativeMetrics\n        description: Behavioral or quality-based measures\n      - fieldname: reviewFrequency\n        description: How often performance is reviewed\n      - fieldname: probationPeriod\n        description: Length of 