description: "Specific components, libraries, or services to be reused"\n  evces-form:\n    fields:\n      - fieldname: weight\n        description: Relative importance as percentage of total score\n      - fieldname: scoringScale\n        description: "Scale used, e.g. 1-5, 1-10, Pass/Fail"\n      - fieldname: minimumThreshold\n        description: "Minimum acceptable score, e.g. 3 out of 5"\n      - fieldname: eliminatory\n        description: "Yes / No — does failing this criterion disqualify the component?"\n  evcep-form:\n    fields:\n      - fieldname: evidenceRequired\n        description: "What proof is needed — benchmark report, vendor attestation, demo"\n      - fieldname: evaluationMethod\n        description: ProofOfConcept / ReferenceCheck / DocumentReview / LoadTest\n      - fieldname: evaluator\n        description: "Who performs this evaluation — architect, security, procurement"\n      - fieldname: evaluationDuration\n        description: Expected time to complete this evaluation\n  evceg-form:\n    fields:\n      - fieldname: scoringGuidelineLow\n        description: What a lowest-tier score looks like\n      - fieldname: scoringGuidelineMid\n        description: What a mid-tier score looks like\n      - fieldname: scoringGuidelineHigh\n        description: What the highest score looks like\n      - fieldname: applicableTo\n        description: Which component categories this criterion applies to\n  cmpvd-form:\n    fields:\n      - fieldname: version\n        description: Current version in use or targeted\n      - fieldname: purpose\n        description: Why this component is needed in business terms\n      - fieldname: vendorName\n        description: Company or organization behind the component\n      - fieldname: vendorStability\n        description: "Financial health, market position, acquisition risk"\n  cmpmt-form:\n    fields:\n      - fieldname: maturityLevel\n        description: Emerging / Growing / Mature / Declining / EndOfLife\n      - fieldname: communitySize\n        description: "GitHub stars, contributors, forum activity"\n      - fieldname: releaseFrequency\n        description: How often new versions are published\n  cmpsp-form:\n    fields:\n      - fieldname: supportModel\n        description: CommunityOnly / VendorPaid / Hybrid / ManagedService\n      - fieldname: supportTier\n        description: "Contracted support level, e.g. Enterprise Gold 24/7"\n      - fieldname: securityTrackingUrl\n        description: CVE feed or security bulletin URL\n  cmppf-form:\n    fields:\n      - fieldname: performanceBenchmark\n        description: Key throughput/latency figures\n      - fieldname: scalabilityLimit\n        description: Known upper limits\n  cmpdp-form:\n    fields:\n      - fieldname: deploymentModel\n        description: OnPremise / SaaS / PaaS / Hybrid / Container / Serverless\n      - fieldname: resourceFootprint\n        description: "CPU, memory, disk, network baseline requirements"\n  coco-form:\n    fields:\n      - fieldname: totalCostFirstYear\n        description: "Total cost including license, infra, integration, training"\n      - fieldname: totalCostOngoing\n        description: Recurring annual cost after first year\n  cc-form:\n    fields:\n      - fieldname: complianceCertifications\n        description: "SOC2, ISO 27001, HIPAA, FedRAMP, PCI-DSS, etc."\n      - fieldname: trainingRequirement\n        description: Estimated ramp-up effort\n  cori-form:\n    fields:\n      - fieldname: replacementDifficulty\n        description: Low / Medium / High / Extreme — with justification\n      - fieldname: lockInFactors\n        description: "Proprietary formats, data migration cost"\n      - fieldname: integrationComplexity\n        description: Effort to integrate.\n  cien-form:\n    fields:\n      - fieldname: port\n        description: "Default network port, e.g. 443, 5432, 6379"\n      - fieldname: basePath\n        description: "Root URL or queue name, e.g. /api/v2, orders.events"\n      - fieldname: rateLimitRequests\n        description: Maximum requests per minute allowed\n  cies-form:\n    fields:\n      - fieldname: authenticationMethod\n        description: OAuth2 / APIKey / mTLS / SAML / BasicAuth / None\n      - fieldname: authorizationModel\n        description: RBAC / ABAC / ScopeBased / ACL — how permissions are enforced\n      - fieldname: tlsRequired\n        description: "Required / Optional / NotSupported, minimum TLS version"\n  cied-form:\n    fields:\n      - fieldname: dataFormatRequest\n        description: JSON / XML / Protobuf / Avro / CSV / Binary\n      - fieldname: dataFormatResponse\n        description: JSON / XML / Protobuf / Avro / CSV / Binary\n      - fieldname: versioningScheme\n        description: URLPath / Header / QueryParam / ContentNegotiation\n      - fieldname: currentApiVersion\n        description: "Currently active version, e.g. v2.3"\n      - fieldname: backwardCompatibility\n        description: How breaking changes are handled and communicated\n  coinensl-form:\n    fields:\n      - fieldname: slaAvailability\n        description: "Target uptime, e.g. 99.95%"\n      - fieldname: slaLatencyP99\n        description: "99th percentile response time target, e.g. <200ms"\n      - fieldname: healthCheckEndpoint\n        description: URL or mechanism for liveness/readiness probes\n      - fieldname: monitoringEndpoint\n        description: "Prometheus, StatsD, or custom metrics endpoint"\n  cieo-form:\n    fields:\n      - fieldname: retryPolicy\n        description: "Exponential backoff params, max retries, idempotency"\n      - fieldname: documentationUrl\n        description: "Link to OpenAPI spec, SDK docs, or integration guide"\n      - fieldname: description\n        description: Purpose and usage context for this interface\n  clec-form:\n    fields:\n      - fieldname: costInitial\n        description: One-time purchase or setup fee\n      - fieldname: costRecurring\n        description: Annual/monthly renewal amount\n      - fieldname: renewalDate\n        description: Next renewal deadline\n      - fieldname: autoRenewal\n        description: Yes / No — and cancellation notice period\n  cler-form:\n    fields:\n      - fieldname: redistributionRights\n        description: "Can the component be redistributed to end users or partners?"\n      - fieldname: sublicensingAllowed\n        description: Whether sublicensing to third parties is permitted\n      - fieldname: openSourceObligations\n        description: "Copyleft, attribution, source disclosure requirements"\n      - fieldname: copyleftScope\n        description: FileLevel / LibraryLevel / ProjectWide — copyleft impact\n  colienco-form:\n    fields:\n      - fieldname: auditRights\n        description: "Can vendor audit our usage? Frequency and notice period"\n      - fieldname: geographicRestrictions\n        description: Countries or regions where use is prohibited or restricted\n      - fieldname: exportControlClassification\n        description: ECCN classification or export restriction category\n  colienca-form:\n    fields:\n      - fieldname: usageMetricTracked\n        description: "What is metered — API calls, users, data volume, CPU hours"\n      - fieldname: licensedCapacity\n        description: Maximum allowed under current license\n      - fieldname: overagePolicy\n        description: "What happens when capacity is exceeded — throttle, surcharge, block"\n  comlicentcon-form:\n    fields:\n      - fieldname: terminationClause\n        description: Early termination penalties and data export rights\n  cres-form:\n    fields:\n      - fieldname: vendorSupportContact\n        description: "How to reach vendor support — portal, email, phone"\n      - fieldname: vendorSupportHours\n        description: "Availability window, e.g. 24/7 or Mon-Fri 9-17 CET"\n  coreensl-form:\n    fields:\n      - fieldname: slaUptimeTarget\n        description: "Internal uptime commitment, e.g. 99.9%"\n      - fieldname: slaResponseCritical\n        description: Max time to acknowledge a P1/critical incident\n      - fieldname: slaResolutionCritical\n        description: Max time to resolve or workaround a P1 incident\n  creo-form:\n    fields:\n      - fieldname: patchCadence\n        description: "How quickly patches are applied, e.g. Critical: 24h, Normal: 14d"\n      - fieldname: securityVulnProcess\n        description: Steps from CVE disclosure to remediation\n      - fieldname: securityScanFrequency\n        description: How often dependency/vulnerability scans run\n      - fieldname: updateStrategy\n        description: BlueGreen / Rolling / Canary / MaintenanceWindow\n      - fieldname: changeApprovalProcess\n        description: Who approves upgrades and configuration changes\n      - fieldname: monitoringOwner\n        description: Who maintains dashboards and alerts\n  creg-form:\n    fields:\n      - fieldname: knowledgeBaseLocation\n        description: "Where runbooks, FAQs, and tribal knowledge are stored"\n      - fieldname: budgetAllocationAnnual\n        description: Budget allocated for this component — license + ops + training\n      - fieldname: reviewFrequency\n        description: "How often the component is formally reviewed — quarterly, annually"\n      - fieldname: capacityPlanningOwner\n        description: Who monitors usage and plans for growth\n  rdec-form:\n    fields:\n      - fieldname: versionConstraint\n        description: "Pinned / Range / Minimum, e.g. >=3.2 <4.0"\n      - fieldname: criticality\n        description: Impact if unavailable.\n      - fieldname: purpose\n        description: Why this dependency exists\n  rdes-form:\n    fields:\n      - fieldname: startupOrder\n        description: Boot sequence priority (1 = first)\n      - fieldname: startupTimeout\n        description: Max wait time before declaring startup failure\n      - fieldname: healthCheckMethod\n        description: "How to verify this dependency is healthy — endpoint, ping, query"\n      - fieldname: healthCheckInterval\n        description: "How often health is verified, e.g. 30s"\n  rder-form:\n    fields:\n      - fieldname: failoverBehavior\n        description: GracefulDegradation / CircuitBreaker / Retry / FailFast\n      - fieldname: fallbackComponent\n        description: What to use if this dependency fails or is unavailable\n      - fieldname: cacheStrategy\n        description: How responses/data from this dependency are cached\n  rdei-form:\n    fields:\n      - fieldname: dataFlowDirection\n        description: ReadOnly / WriteOnly / Bidirectional / EventDriven\n      - fieldname: networkRequired\n        description: Local / LAN / Internet — and impact of network partition\n      - fieldname: latencyTolerance\n        description: Max acceptable latency to this dependency\n  rudeenri-form:\n    fields:\n      - fieldname: transitiveRisk\n        description: Key risks from this dependency\'s own dependencies\n      - fieldname: compatibilityMatrix\n        description: Known incompatibilities with other components in our stack\n  mdec-form:\n    fields:\n      - fieldname: dependencyType\n        description: BuildTime / TestOnly / DevOnly / Tooling\n      - fieldname: criticality\n        description: Impact if update breaks.\n      - fieldname: purpose\n        description: Why this maintenance dependency exists\n  mdeu-form:\n    fields:\n      - fieldname: updateStrategy\n        description: "How dependency updates are adopted — auto, manual review, staged"\n      - fieldname: updateFrequency\n        description: "How often we update this dependency — weekly, monthly, quarterly"\n      - fieldname: coordinatedUpdateSequence\n        description: Order in which related components must be updated together\n      - fieldname: breakingChangePolicy\n        description: "How breaking changes are handled — pin version, adapt, delay"\n  mder-form:\n    fields:\n      - fieldname: compatibilityMatrix\n        description: Known incompatibilities with other components in our stack\n      - fieldname: alternative\n        description: Replacement if this dependency is abandoned or EOL\n      - fieldname: transitiveRisk\n        description: Key risks from this dependency\'s own dependencies\n      - fieldname: securityPatchSla\n        description: "How quickly security patches must be applied, e.g. Critical: 24h"\n  cred-form:\n    fields:\n      - fieldname: riskDescription\n        description: Detailed explanation of the risk scenario\n      - fieldname: riskCategory\n        description: Technical / Vendor / Security / Compliance / Operational / Financial\n  crea-form:\n    fields:\n      - fieldname: probability\n        description: Qualitative likelihood band for this component risk.\n      - fieldname: impact\n        description: Qualitative consequence band if the risk lands.\n      - fieldname: riskScore\n        description: Calculated score (probability × impact)\n      - fieldname: riskTrend\n        description: Increasing / Stable / Decreasing — direction since last review\n  coriende-form:\n    fields:\n      - fieldname: detectionMethod\n        description: How we would know this risk is materializing\n      - fieldname: earlyWarningIndicators\n        description: Metrics or signals that precede this risk event\n      - fieldname: monitoringMechanism\n        description: "Dashboards, alerts, or scans that track this risk"\n  crem-form:\n    fields:\n      - fieldname: mitigationStrategy\n        description: Actions to reduce probability or impact\n      - fieldname: mitigationStatus\n        description: NotStarted / InProgress / Implemented / Verified\n      - fieldname: mitigationCost\n        description: Budget required to implement mitigation\n      - fieldname: residualRisk\n        description: Risk level remaining after mitigation.\n      - fieldname: contingencyTrigger\n        description: "Condition activating the contingency plan, e.g. No release for 12 months"\n  coriengo-form:\n    fields:\n      - fieldname: riskOwner\n        description: Person accountable for managing this risk\n      - fieldname: reviewFrequency\n        description: How often this risk is reassessed\n      - fieldname: relatedRisks\n        description: "Other component risks that correlate or cascade — risk section ids (CMRS-RISK-…), comma-separated"\n      - fieldname: acceptanceCriteria\n        description: Under what conditions is this risk formally accepted\n  cper-form:\n    fields:\n      - fieldname: riskRef\n        description: The component risk this plan addresses — a risk section id (CMRS-RISK-…)\n      - fieldname: componentRef\n        description: The component this plan covers — a component section id (CMPNT-COMP-…)\n  cpea-form:\n    fields:\n      - fieldname: triggerDetection\n        description: "How the trigger is detected — alert, manual report, monitoring"\n      - fieldname: immediateActions\n        description: First steps within minutes of trigger (containment)\n      - fieldname: recoveryActions\n        description: Steps to restore full operation\n  coplenre-form:\n    fields:\n      - fieldname: responsibleParty\n        description: Primary person/team who executes this plan\n      - fieldname: supportTeams\n        description: Additional teams involved in execution\n      - fieldname: targetRecoveryTime\n        description: Maximum acceptable downtime\n      - fieldname: targetRecoveryPoint\n        description: Maximum acceptable data loss window\n  cpec-form:\n    fields:\n      - fieldname: communicationPlan\n        description: "Who is notified, how, and in what order"\n      - fieldname: customerCommunication\n        description: External messaging template or process\n  cpet-form:\n    fields:\n      - fieldname: testingFrequency\n        description: "How often this plan is tested — quarterly, annually"\n      - fieldname: lastTestedDate\n        description: When this plan was last exercised\n      - fieldname: lastTestResult\n        description: Pass / Fail and key findings from last test\n      - fieldname: dependencies\n        description: "What this plan requires to execute — tools, access, backups"\n      - fieldname: estimatedCost\n        description: Estimated cost of executing this contingency\n      - fieldname: priority\n        description: Relative priority if multiple plans compete for resources\n      - fieldname: fallbackPlan\n        description: What to do if this contingency plan itself fails\n      - fieldname: documentLocation\n        description: Where the detailed step-by-step runbook is stored\n  uacst-form:\n    fields:\n      - fieldname: stateModel\n        description: "Linear | Graph | Hierarchical — how states relate to each other"\n      - fieldname: initialState\n        description: "State assigned at account creation (e.g., Pending Verification)"\n      - fieldname: activeState\n        description: Fully operational account state name\n      - fieldname: suspendedState\n        description: Temporarily restricted state name\n      - fieldname: lockedState\n        description: "Account locked due to security policy (e.g., failed logins)"\n      - fieldname: deactivatedState\n        description: "Administratively disabled, recoverable"\n      - fieldname: archivedState\n        description: Read-only historical state before permanent deletion\n      - fieldname: deletedState\n        description: Permanently removed or anonymized\n      - fieldname: customStates\n        description: Additional project-specific states (comma-separated)\n      - fieldname: stateVisibility\n        description: Which states are visible to the user vs. admin-only\n      - fieldname: stateTransitionDiagramRef\n        description: Reference to a state transition diagram (mermaid or external)\n  urreg-form:\n    fields:\n      - fieldname: registrationMethods\n        description: "SelfRegistration | Invitation | AdminProvisioned | BulkImport | ExternalIdP"\n      - fieldname: selfRegistrationEnabled\n        description: "Yes | No | PerCategory — whether users can self-register"\n      - fieldname: identityProofingLevel\n        description: "None | Email | Phone | Document | InPerson — per NIST SP 800-63A IAL"\n      - fieldname: emailVerificationRequired\n        description: "Yes | No | Optional"\n      - fieldname: phoneVerificationRequired\n        description: "Yes | No | Optional"\n      - fieldname: captchaRequired\n        description: "Yes | No — bot prevention during self-registration"\n      - fieldname: invitationExpiryPeriod\n        description: "Duration before invitation link expires (e.g., 48h, 7d)"\n      - fieldname: approvalRequired\n        description: "Yes | No — whether registration needs manual approval"\n      - fieldname: approvalWorkflow\n        description: "Single Approver | Multi-Level | Auto-Approved — workflow type"\n      - fieldname: approverRole\n        description: Role or person who approves new registrations\n      - fieldname: requiredFieldsAtRegistration\n        description: Comma-separated list of mandatory fields during signup\n      - fieldname: optionalFieldsAtRegistration\n        description: Comma-separated list of optional fields during signup\n      - fieldname: termsAcceptanceRequired\n        description: "Yes | No — must accept terms of service / privacy policy"\n      - fieldname: duplicateDetection\n        description: "How duplicate accounts are detected (email, phone, name matching)"\n      - fieldname: welcomeNotification\n        description: "Email | SMS | InApp | None — notification on successful registration"\n      - fieldname: initialRoleAssignment\n        description: Default role(s) assigned at registration\n      - fieldname: registrationRateLimiting\n        description: Max registrations per IP/time window to prevent abuse\n  acact-form:\n    fields:\n      - fieldname: activationMethod\n        description: "EmailLink | AdminApproval | Automatic | PhoneVerification | Combined"\n      - fieldname: activationLinkExpiry\n        description: "Duration before activation link expires (e.g., 24h)"\n      - fieldname: maxActivationAttempts\n        description: Number of times user can request re-activation\n      - fieldname: activationPrerequisites\n        description: "Conditions that must be met before activation (e.g., email verified, approved)"\n      - fieldname: provisioningOnActivation\n        description: "Resources provisioned when account becomes active (workspace, storage, etc.)"\n      - fieldname: activationNotification\n        description: "Channels notified on activation (email, SMS, admin alert)"\n      - fieldname: activationTimeout\n        description: Time after which unactivated accounts are purged or flagged\n      - fieldname: activationTimeoutAction\n        description: "Delete | Flag | Remind | Escalate — action on timeout"\n      - fieldname: postActivationRedirect\n        description: "Where the user is directed after activation (dashboard, onboarding wizard)"\n      - fieldname: onboardingRequired\n        description: "Yes | No — whether guided onboarding follows activation"\n      - fieldname: onboardingSteps\n        description: "Steps in onboarding flow (profile completion, tutorial, preference setup)"\n  acmod-form:\n    fields:\n      - fieldname: selfModifiableFields\n        description: "Fields the user can change themselves (display name, avatar, preferences)"\n      - fieldname: adminModifiableFields\n        description: "Fields only an administrator can change (role, status, organization)"\n      - fieldname: systemModifiableFields\n        description: "Fields updated automatically (last login, login count, risk score)"\n      - fieldname: emailChangePolicy\n        description: "Re-verification required | Admin approval | Confirmation to old+new email"\n      - fieldname: phoneChangePolicy\n        description: "Verification via old number | Admin approval"\n      - fieldname: nameChangePolicy\n        description: "Self-service | RequiresVerification | AdminOnly"\n      - fieldname: roleChangeApproval\n        description: "Who approves role changes (manager, admin, auto-approved for certain changes)"\n      - fieldname: bulkModificationSupport\n        description: "Yes | No — whether batch attribute updates are supported"\n      - fieldname: changeAuditLogging\n        description: "All changes | SensitiveOnly | None — audit trail granularity"\n      - fieldname: changeNotification\n        description: "User | Admin | Both | None — who receives notification of changes"\n      - fieldname: historicalVersioning\n        description: "Yes | No — whether previous attribute values are preserved"\n      - fieldname: reverificationTriggers\n        description: "Which changes trigger re-verification (email, password, security question)"\n      - fieldname: modificationRateLimiting\n        description: "Limits on how frequently attributes can be changed (e.g., email max 1/30d)"\n      - fieldname: modificationCooldownPeriod\n        description: Waiting period after sensitive changes before full access resumes\n  acdea-form:\n    fields:\n      - fieldname: deactivationTriggers\n        description: "Manual | Inactivity | PolicyViolation | ContractEnd | SecurityIncident"\n      - fieldname: inactivityThreshold\n        description: "Period of inactivity before automatic deactivation (e.g., 90d, 180d)"\n      - fieldname: inactivityWarningPeriod\n        description: "Advance notice before deactivation (e.g., warn 14d before deactivation)"\n      - fieldname: deactivationApproval\n        description: "Who can deactivate accounts (admin, manager, system, self)"\n      - fieldname: immediateDeactivationCases\n        description: "Cases where deactivation is immediate without warning (security breach, termination)"\n      - fieldname: deactivatedAccountAccess\n        description: Whether deactivated account data remains accessible to admins\n      - fieldname: deactivationEffects\n        description: "LoginBlocked | ApiKeysRevoked | SessionsTerminated | DataPreserved"\n      - fieldname: reactivationPolicy\n        description: "UserRequest | AdminOnly | AutoOnLogin | NotAllowed — how accounts are reactivated"\n      - fieldname: reactivationApproval\n        description: "Who approves reactivation (original approver, admin, manager)"\n      - fieldname: reactivationReverification\n        description: "PasswordReset | MFA | IdentityProofing — verification at reactivation"\n      - fieldname: maxDeactivationPeriod\n        description: Maximum time an account can stay deactivated before escalation to deletion\n      - fieldname: deactivationNotification\n        description: "User | Admin | Manager | All — channels notified on deactivation"\n      - fieldname: gracePeriodAfterDeactivation\n        description: Window during which deactivation is easily reversible\n      - fieldname: dataPreservationDuration\n        description: "How long deactivated account data is preserved (30d, 1y, indefinitely)"\n  acdel-form:\n    fields:\n      - fieldname: deletionTriggers\n        description: "UserRequest | RetentionExpiry | AdminDecision | RegulatoryOrder"\n      - fieldname: deletionApproval\n        description: "Who approves deletion (admin, data protection officer, auto-approved)"\n      - fieldname: softDeleteEnabled\n        description: "Yes | No — whether accounts are soft-deleted before hard deletion"\n      - fieldname: softDeleteRetention\n        description: "Duration in soft-deleted state before permanent removal (e.g., 30d, 90d)"\n      - fieldname: permanentDeletionProcess\n        description: "Anonymize | Purge | Archive — what happens to data on permanent deletion"\n      - fieldname: dataAnonymizationStrategy\n        description: "Fields anonymized, pseudonymization method, referential integrity handling"\n      - fieldname: retainedDataAfterDeletion\n        description: "Data kept for legal/audit reasons (transaction logs, audit trails)"\n      - fieldname: retentionPeriodAfterDeletion\n        description: How long retained data is kept post-deletion\n      - fieldname: dataExportBeforeDeletion\n        description: "Yes | No — whether users can export their data before deletion"\n      - fieldname: exportFormats\n        description: "JSON | CSV | XML | PDF — formats for data export"\n      - fieldname: cascadeDeletionBehavior\n        description: "What happens to associated content (posts, files, records) on user deletion"\n      - fieldname: deletionConfirmation\n        description: "PasswordEntry | EmailConfirmation | WaitingPeriod — confirmation method"\n      - fieldname: deletionNotification\n        description: "User | Admin | DPO | All — who is notified on deletion"\n      - fieldname: rightToErasureCompliance\n        description: "GDPR Art.17 | CCPA | None — applicable right-to-be-forgotten regulations"\n      - fieldname: erasureResponseTime\n        description: "Maximum time to fulfill an erasure request (e.g., 30 days per GDPR)"\n      - fieldname: thirdPartyDataDeletion\n        description: How data shared with third parties is removed or anonymized\n  ultap-form:\n    fields:\n      - fieldname: approvalRequired\n        description: "Yes | No — whether manual approval is needed"\n      - fieldname: approverRole\n        description: "Role that must approve (admin, manager, DPO)"\n      - fieldname: approvalSla\n        description: Maximum time allowed for approval decision\n  ultef-form:\n    fields:\n      - fieldname: sideEffects\n        description: "Actions performed on transition (revoke tokens, send email, deprovision)"\n      - fieldname: notificationRecipients\n        description: "Who is notified (user, admin, manager)"\n      - fieldname: notificationChannels\n        description: "Email | SMS | InApp | Webhook"\n  ultau-form:\n    fields:\n      - fieldname: reversible\n        description: "Yes | No — whether this transition can be undone"\n      - fieldname: reverseTransitionName\n        description: Name of the reverse transition if applicable\n      - fieldname: automationSupported\n        description: "Yes | No — whether this transition can be automated"\n  ultrs-form:\n    fields:\n      - fieldname: transitionModel\n        description: "StateMachine | Workflow | Hybrid — how transitions are modeled"\n      - fieldname: approvalPolicyDefault\n        description: "SingleApprover | DualControl | AutoApproved — default for all transitions"\n      - fieldname: escalationPolicy\n        description: "What happens if approval is not granted within SLA (auto-deny, escalate, remind)"\n      - fieldname: escalationTimeframe\n        description: "Time before pending approval is escalated (e.g., 48h)"\n      - fieldname: auditTrailRequired\n        description: "Yes | No — whether every transition is logged"\n      - fieldname: notificationOnTransition\n        description: "User | Approver | Admin | All — who is notified on state change"\n      - fieldname: bulkTransitionSupport\n        description: "Yes | No — whether multiple accounts can transition at once"\n      - fieldname: automatedTransitions\n        description: "Transitions triggered automatically (inactivity → deactivated, expiry → deleted)"\n      - fieldname: transitionUndoPolicy\n        description: Which transitions are reversible and within what time window\n  ssacm-form:\n    fields:\n      - fieldname: profileUpdateEnabled\n        description: "Yes | No — users can update their own profile information"\n      - fieldname: passwordChangeEnabled\n        description: "Yes | No — users can change their own password"\n      - fieldname: passwordResetEnabled\n        description: "Yes | No — users can reset forgotten passwords"\n      - fieldname: passwordResetMethods\n        description: "Email | SMS | SecurityQuestions | AdminAssisted"\n      - fieldname: mfaEnrollmentSelfService\n        description: "Yes | No — users can enroll/change MFA devices"\n      - fieldname: accountDeactivationSelfService\n        description: "Yes | No — users can deactivate their own account"\n      - fieldname: accountDeletionSelfService\n        description: "Yes | No — users can request deletion of their own account"\n      - fieldname: dataExportSelfService\n        description: "Yes | No — users can export their own data"\n      - fieldname: sessionManagementSelfService\n        description: "Yes | No — users can view and terminate their active sessions"\n      - fieldname: apiKeyManagementSelfService\n        description: "Yes | No — users can create/revoke their own API keys"\n      - fieldname: notificationPreferences\n        description: "Yes | No — users can configure their notification preferences"\n      - fieldname: delegationEnabled\n        description: "Yes | No — users can delegate account actions to another user"\n      - fieldname: delegationScope\n        description: "What actions can be delegated (read, write, approve)"\n      - fieldname: accountRecoveryProcess\n        description: "Steps when a user loses all credentials (identity re-proofing, admin reset)"\n  saclc-serv-form:\n    fields:\n      - fieldname: serviceAccountTypes\n        description: "API Client | Bot | SystemIntegration | ScheduledJob | DeviceIdentity"\n      - fieldname: creationProcess\n        description: "How service accounts are created (admin, DevOps pipeline, self-service)"\n      - fieldname: creationApproval\n        description: "Who approves service account creation (security team, admin)"\n      - fieldname: ownerAssignment\n        description: "Yes | No — whether each service account must have a human owner"\n      - fieldname: ownerReviewFrequency\n        description: "How often owners must recertify service accounts (quarterly, annually)"\n      - fieldname: credentialRotationPolicy\n        description: "How often credentials (keys, secrets, certificates) must be rotated"\n      - fieldname: credentialStorageMethod\n        description: "VaultService | EnvironmentVariable | SecretManager | HSM"\n      - fieldname: scopeLimitation\n        description: Principle of least privilege — minimum permissions for service accounts\n      - fieldname: ipRestriction\n        description: "Yes | No — whether service accounts are restricted to specific IPs"\n      - fieldname: expirationPolicy\n        description: "Whether service accounts expire and after how long (e.g., 1y, never)"\n      - fieldname: renewalProcess\n        description: Steps to renew an expiring service account\n      - fieldname: decommissioningProcess\n        description: "How service accounts are retired (revoke, archive, delete)"\n      - fieldname: monitoringRequirements\n        description: "Anomaly detection, usage thresholds, alerting for service accounts"\n      - fieldname: serviceAccountNamingConvention\n        description: "Naming pattern for service accounts (e.g., svc-{app}-{environment})"\n      - fieldname: documentationRequirements\n        description: "What must be documented for each service account (purpose, owner, scope)"\n  idsoenco-form:\n    fields:\n      - fieldname: sourceEndpoint\n        description: Connection endpoint URL or hostname\n      - fieldname: sourceProtocol\n        description: LDAP / LDAPS / SCIM / SAML / OIDC / REST / DatabaseDirect / Custom\n      - fieldname: priority\n        description: Primary / Secondary / Tertiary / Fallback — source precedence\n      - fieldname: trustLevel\n        description: Full / High / Medium / Low / Untrusted — degree of trust in identities from this source\n      - fieldname: authoritative\n        description: Yes / No — whether this source is the golden record for identity attributes\n  isel-form:\n    fields:\n      - fieldname: synchronizationMode\n        description: RealTime / Scheduled / OnDemand / EventDriven / Manual\n      - fieldname: synchronizationFrequency\n        description: "Sync interval if scheduled, e.g. 15min, 1h, 24h, weekly"\n      - fieldname: provisioningMethod\n        description: JustInTime / PreProvisioned / SCIM / Manual / Automated\n      - fieldname: deprovisioningMethod\n        description: Automatic / Manual / Delayed / Cascading — how identities are removed\n      - fieldname: conflictResolution\n        description: SourceWins / TargetWins / MostRecent / ManualReview / MergeAttributes\n  isem-form:\n    fields:\n      - fieldname: attributeFilter\n        description: "Which attributes are imported, e.g. all, name+email+groups, custom list"\n      - fieldname: groupMappingEnabled\n        description: Yes / No — whether groups/roles from this source are mapped to application roles\n  iseo-form:\n    fields:\n      - fieldname: failoverBehavior\n        description: RetryWithBackoff / FallbackToCache / FailClosed / FailOpen\n      - fieldname: enabled\n        description: Yes / No — whether this source is currently active\n      - fieldname: description\n        description: Detailed description of this identity source and its role\n  ivpd-form:\n    fields:\n      - fieldname: requiredDocuments\n        description: "Document types required for proofing, e.g. Government ID, Passport, Utility Bill, None"\n      - fieldname: documentVerificationMethod\n        description: VisualInspection / OCR / NFC / DatabaseCheck / BiometricMatch / ThirdPartyService\n      - fieldname: biometricVerification\n        description: None / FaceMatch / Fingerprint / LivenessDetection\n  ivpm-form:\n    fields:\n      - fieldname: emailVerification\n        description: Required / Optional / NotApplicable\n      - fieldname: phoneVerification\n        description: Required / Optional / NotApplicable\n      - fieldname: verificationServiceProvider\n        description: "Third-party provider, e.g. Jumio, Onfido, LexisNexis, Internal"\n  ivpw-form:\n    fields:\n      - fieldname: verificationSteps\n        description: "Ordered proofing steps, e.g. EmailConfirm → DocUpload → FaceMatch → AdminApproval"\n      - fieldname: supervisorApprovalRequired\n        description: Yes / No / ForExternalOnly — whether a supervisor must approve identity proofing\n      - fieldname: proofingChannels\n        description: InPerson / Remote / Hybrid — where identity proofing occurs\n  ivpl-form:\n    fields:\n      - fieldname: reverificationTriggers\n        description: "Events triggering re-proofing, e.g. RoleChange, SuspiciousActivity, Periodic, DataBreach"\n      - fieldname: reverificationPeriod\n        description: "How often identities must be re-verified, e.g. 1y, 2y, never, onRiskEvent"\n      - fieldname: verificationRecordRetention\n        description: "How long verification evidence is retained, e.g. 5y, 7y, permanent"\n  ivpf-form:\n    fields:\n      - fieldname: failedVerificationPolicy\n        description: Deny / RetryLimited / ManualEscalation / AlternativeProofing\n      - fieldname: maxVerificationAttempts\n        description: "Maximum proofing attempts before lockout, e.g. 3, 5"\n  idprma-form:\n    fields:\n      - fieldname: attributeMapping\n        description: How IdP claims/attributes map to application user attributes\n      - fieldname: groupClaimName\n        description: Claim/attribute containing group memberships\n      - fieldname: defaultRoles\n        description: Roles assigned by default to users from this IdP\n      - fieldname: justInTimeProvisioning\n        description: Yes / No — whether accounts are auto-created on first login\n      - fieldname: accountLinkingStrategy\n        description: EmailMatch / ExternalId / ManualLink / None\n  idprtr-form:\n    fields:\n      - fieldname: trustLevel\n        description: Full / High / Medium / Low\n      - fieldname: federationAgreement\n        description: Reference to federation agreement governing this IdP\n      - fieldname: mfaCapability\n        description: Supported / Required / NotSupported\n      - fieldname: failoverIdp\n        description: Backup identity provider if unavailable\n  idprse-form:\n    fields:\n      - fieldname: certificateManagement\n        description: How signing/encryption certificates are managed\n      - fieldname: tokenSigningAlgorithm\n        description: RS256 / RS384 / RS512 / ES256 / EdDSA\n      - fieldname: encryptionRequired\n        description: Yes / No — whether assertions/tokens must be encrypted\n  ssopf-form:\n    fields:\n      - fieldname: ssoGatewayProduct\n        description: "Product/service acting as SSO hub, e.g. Keycloak, PingGateway, Azure AD"\n      - fieldname: sessionPropagationMethod\n        description: SharedCookie / TokenRelay / BackChannel / FrontChannelRedirect\n      - fieldname: crossDomainTrustModel\n        description: SharedIdP / FederatedTrust / BrokeredTrust / None\n      - fieldname: identityFederationEnabled\n        description: Yes / No — whether identities federate across organizational boundaries\n  ssops-form:\n    fields:\n      - fieldname: logoutPropagation\n        description: SingleLogout / LocalOnly / BestEffort — how logout propagates across SSO-connected apps\n      - fieldname: logoutProtocol\n        description: FrontChannel / BackChannel / Both — SLO mechanism\n      - fieldname: ssoSessionLifetime\n        description: "Maximum SSO session duration before re-authentication, e.g. 8h, 24h, 30d"\n      - fieldname: ssoIdleTimeout\n        description: "Idle timeout before SSO session expires, e.g. 30min, 1h, 4h"\n  ssopa-form:\n    fields:\n      - fieldname: accountLinkingStrategy\n        description: AutomaticByEmail / AutomaticByExternalId / UserInitiated / AdminManaged / None\n      - fieldname: consentRequirements\n        description: None / FirstLoginOnly / PerApplication / PerScope / Periodic\n      - fieldname: ssoPortalUrl\n        description: URL for the central SSO portal or application launcher\n      - fieldname: ssoBypassRules\n        description: "Scenarios where SSO is bypassed, e.g. ServiceAccounts, LocalAdminFallback, BreakGlass"\n  ssopo-form:\n    fields:\n      - fieldname: desktopSsoIntegration\n        description: Kerberos / WindowsIntegrated / None — integration with desktop/OS authentication\n      - fieldname: mobileSsoStrategy\n        description: SharedKeychain / AppLinks / BrowserBased / NativeSDK — SSO approach for mobile apps\n      - fieldname: ssoMonitoring\n        description: "How SSO health and usage is monitored, e.g. IdPHealthCheck, LoginSuccessRate"\n  srpf-form:\n    fields:\n      - fieldname: optionalFields\n        description: "Fields available but not required, e.g. organization, jobTitle, avatar"\n      - fieldname: termsAcceptanceRequired\n        description: Yes / No — whether ToS/privacy policy acceptance is required\n  srpbp-form:\n    fields:\n      - fieldname: captchaRequired\n        description: Yes / No / Adaptive — whether CAPTCHA/bot protection is required\n      - fieldname: captchaProvider\n        description: reCAPTCHAv2 / reCAPTCHAv3 / hCaptcha / Turnstile / Custom\n  srpv-form:\n    fields:\n      - fieldname: emailVerificationRequired\n        description: Yes / No — whether email must be verified before account is active\n      - fieldname: emailVerificationMethod\n        description: ClickLink / EnterCode / MagicLink\n      - fieldname: phoneVerificationRequired\n        description: Yes / No — whether phone must be verified\n      - fieldname: phoneVerificationMethod\n        description: SMS / VoiceCall / WhatsApp\n  srpa-form:\n    fields:\n      - fieldname: approvalRequired\n        description: Yes / No / Conditional — whether admin approval is needed before activation\n      - fieldname: approvalWorkflow\n        description: SingleApprover / DualApproval / ManagerApproval / AutoApprove\n      - fieldname: defaultRole\n        description: "Role assigned to newly self-registered users, e.g. BasicUser, Viewer, Pending"\n      - fieldname: defaultGroup\n        description: Group assigned to newly self-registered users\n      - fieldname: accountActivationDelay\n        description: "Delay between registration and account becoming usable, e.g. immediate, afterVerification, 24h"\n      - fieldname: welcomeNotification\n        description: Yes / No — whether a welcome email/message is sent after registration\n  srps-form:\n    fields:\n      - fieldname: allowedEmailDomains\n        description: "Domain restrictions for registration, e.g. *, company.com, *.edu"\n      - fieldname: blockedEmailDomains\n        description: "Domains blocked from registration, e.g. tempmail.com, guerrillamail.com"\n      - fieldname: duplicateDetectionMethod\n        description: EmailUniqueness / PhoneUniqueness / NameFuzzyMatch / None\n      - fieldname: rateLimiting\n        description: "Registration rate limits, e.g. 5/hour per IP, 10/day per domain"\n  iamet-form:\n    fields:\n      - fieldname: transformationRule\n        description: None / Lowercase / Uppercase / Trim / RegexExtract / Concatenate / MapValues / Custom\n      - fieldname: transformationExpression\n        description: "Expression if Custom/RegexExtract, e.g. {firstName} {lastName}"\n      - fieldname: defaultValue\n        description: Value used when source attribute is missing or null\n      - fieldname: multiValueHandling\n        description: FirstValue / AllValues / Concatenate / PrimaryOnly\n  iames-form:\n    fields:\n      - fieldname: mandatory\n        description: Yes / No — whether this attribute must be present for identity to be valid\n      - fieldname: syncDirection\n        description: SourceToTarget / TargetToSource / Bidirectional / OneTimeImport\n      - fieldname: conflictResolution\n        description: SourceWins / TargetWins / MostRecent / ManualReview — when source and target values differ\n  iameg-form:\n    fields:\n      - fieldname: piiClassification\n        description: None / PII / SensitivePII / SpecialCategory — data sensitivity for GDPR/compliance\n      - fieldname: description\n        description: Purpose and context for this attribute mapping\n  mc-form:\n    fields:\n      - fieldname: mfaRequired\n        description: "Yes | No | Conditional — whether MFA is mandatory"\n      - fieldname: mfaEnforcementScope\n        description: "AllUsers | AdminOnly | PrivilegedRoles | ExternalAccess | Conditional"\n      - fieldname: defaultSecondFactor\n        description: "TOTP | Push | FIDO2 | SMS | Email | HardwareToken"\n      - fieldname: allowedSecondFactors\n        description: Comma-separated list of permitted second-factor types\n      - fieldname: assuranceLevelTarget\n        description: "AAL1 | AAL2 | AAL3 — target NIST authentication assurance level"\n      - fieldname: phishingResistanceRequired\n        description: "Yes | No — whether phishing-resistant authenticators are required (AAL3)"\n      - fieldname: stepUpAuthenticationEnabled\n        description: "Yes | No — whether sensitive operations trigger higher AAL re-authentication"\n      - fieldname: stepUpTriggers\n        description: "Operations that trigger step-up (payment, admin actions, data export)"\n      - fieldname: rememberDevicePolicy\n        description: "Duration a device is remembered before MFA re-prompt (e.g., 30d, never)"\n      - fieldname: recoveryCodePolicy\n        description: How many one-time recovery codes are issued and their validity\n      - fieldname: enrollmentGracePeriod\n        description: "Time allowed for users to enroll MFA after it becomes required (e.g., 14d)"\n      - fieldname: mfaBypassPolicy\n        description: "Conditions under which MFA can be bypassed (break-glass, service accounts)"\n  sp-form:\n    fields:\n      - fieldname: ssoEnabled\n        description: "Yes | No — whether SSO is implemented"\n      - fieldname: ssoProtocol\n        description: "SAML2.0 | OIDC | OAuth2 | WS-Federation | Kerberos"\n      - fieldname: identityProviderType\n        description: "Internal | External | Hybrid — where the IdP is hosted"\n      - fieldname: identityProviderProduct\n        description: "Specific IdP product or service (e.g., Keycloak, Azure AD, Okta, Auth0)"\n      - fieldname: federationProtocol\n        description: "Protocol for cross-organization federation (SAML, OIDC, SCIM)"\n      - fieldname: attributeMapping\n        description: How IdP attributes map to application roles and permissions\n      - fieldname: justInTimeProvisioning\n        description: "Yes | No — whether accounts are auto-created on first SSO login"\n      - fieldname: sessionSynchronization\n        description: "Yes | No — whether logout from one app logs out all SSO-connected apps"\n      - fieldname: singleLogoutEnabled\n        description: "Yes | No — whether SLO (Single Logout) is implemented across services"\n      - fieldname: ssoFallbackMethod\n        description: "Local password | Backup IdP | None — fallback when IdP is unavailable"\n      - fieldname: ssoScopePolicy\n        description: "Which applications are included in SSO (all, internal only, selected)"\n      - fieldname: externalIdpTrustPolicy\n        description: Validation requirements for external identity providers\n  cap-form:\n    fields:\n      - fieldname: certificateAuthEnabled\n        description: "Yes | No — whether certificate-based authentication is supported"\n      - fieldname: certificateTypes\n        description: "X.509 | PIV | CAC | SmartCard — types of certificates accepted"\n      - fieldname: certificateIssuance\n        description: "InternalCA | ExternalCA | SelfSigned — who issues the certificates"\n      - fieldname: certificateAuthority\n        description: CA product or service used for certificate issuance\n      - fieldname: keyStorageRequirement\n        description: "TPM | HSM | SmartCard | SoftwareKeystore — where private keys must be stored"\n      - fieldname: mutualTlsRequired\n        description: "Yes | No — whether mTLS (client certificate) is required for API access"\n      - fieldname: certificateValidation\n        description: "OCSP | CRL | OCSP-Stapling — certificate revocation checking method"\n      - fieldname: certificateLifetime\n        description: "Maximum validity period for certificates (e.g., 1y, 2y)"\n      - fieldname: renewalProcess\n        description: "Automatic | Manual | AdminApproval — certificate renewal method"\n      - fieldname: revocationProcess\n        description: How compromised certificates are revoked and propagated\n      - fieldname: minimumKeyStrength\n        description: "RSA-2048 | RSA-4096 | EC-P256 | EC-P384 — minimum key requirements"\n      - fieldname: fipsComplianceRequired\n        description: "Yes | No — whether FIPS 140-2/3 validated modules are required"\n  bap-form:\n    fields:\n      - fieldname: biometricAuthEnabled\n        description: "Yes | No — whether biometric authentication is supported"\n      - fieldname: biometricModalities\n        description: "Fingerprint | FacialRecognition | IrisScan | VoicePrint — supported modalities"\n      - fieldname: biometricUsageContext\n        description: "DeviceUnlock | TransactionApproval | MfaActivation — when biometrics are used"\n      - fieldname: biometricAsActivationFactor\n        description: "Yes | No — whether biometric is used as MFA activation factor per NIST guidance"\n      - fieldname: localVsCentralComparison\n        description: "Local | Central — where biometric comparison is performed (local preferred)"\n      - fieldname: falseMatchRateTarget\n        description: "Target FMR (e.g., 1:10000 per NIST SP 800-63B)"\n      - fieldname: presentationAttackDetection\n        description: "Yes | No — whether PAD is implemented (required for facial recognition)"\n      - fieldname: maxConsecutiveFailures\n        description: "Maximum failed biometric attempts before fallback (e.g., 5 without PAD, 10 with PAD)"\n      - fieldname: fallbackMethod\n        description: "PIN | Password | AlternateModality — fallback when biometric fails"\n      - fieldname: biometricDataStorage\n        description: "DeviceOnly | EncryptedCentral | Never — where biometric templates are stored"\n      - fieldname: privacyConsiderations\n        description: "Consent requirements, data retention policy, right to withdraw"\n      - fieldname: accessibilityAlternative\n        description: Alternative authentication for users unable to use biometric modalities\n  akmp-form:\n    fields:\n      - fieldname: apiKeyAuthEnabled\n        description: "Yes | No — whether API key authentication is supported"\n      - fieldname: apiKeyTypes\n        description: "Static | Rotating | Scoped | ShortLived — types of API keys supported"\n      - fieldname: keyGenerationMethod\n        description: "Cryptographic random | UUID | JWT — how API keys are generated"\n      - fieldname: keyLength\n        description: "Minimum key length or entropy (e.g., 256-bit, 32 bytes)"\n      - fieldname: keyRotationPolicy\n        description: "Rotation frequency and method (e.g., 90d, automatic, manual)"\n      - fieldname: keyExpirationPolicy\n        description: "Maximum key lifetime (e.g., 1y, never, custom)"\n      - fieldname: keyScopeRestrictions\n        description: "Yes | No — whether API keys can be limited to specific resources/actions"\n      - fieldname: ipAllowlisting\n        description: "Yes | No — whether API keys can be restricted to specific IP addresses"\n      - fieldname: rateLimitingPerKey\n        description: "Yes | No — whether rate limiting is enforced per API key"\n      - fieldname: keyRevocationProcess\n        description: "Immediate | Graceful — how revoked keys stop working"\n      - fieldname: keyStorageGuidance\n        description: "VaultService | EnvironmentVariable | SecretManager — recommended storage"\n      - fieldname: keyAuditLogging\n        description: "Yes | No — whether API key usage is logged for audit