scription: Key steps for switching from old to new system\n      - fieldname: hypercarePeriod\n        description: Duration of intensive post-go-live support\n  stri-form:\n    fields:\n      - fieldname: topRisks\n        description: Key risks specific to this stage\n      - fieldname: riskMitigationStrategies\n        description: Planned responses to top risks\n      - fieldname: contingencyTriggers\n        description: Conditions that activate contingency plans\n      - fieldname: escalationPath\n        description: Escalation process for critical issues\n  stme-form:\n    fields:\n      - fieldname: completionPercentage\n        description: 0-100 — current progress\n      - fieldname: healthIndicator\n        description: Green / Amber / Red\n      - fieldname: scheduleVariance\n        description: Days ahead or behind plan\n      - fieldname: keyPerformanceIndicators\n        description: KPIs to measure stage success\n      - fieldname: successThreshold\n        description: Minimum outcome required to declare success\n  sseo-form:\n    fields:\n      - fieldname: description\n        description: Brief description of this sub-stage or milestone\n      - fieldname: objective\n        description: What this sub-stage aims to achieve\n  sset-form:\n    fields:\n      - fieldname: targetStartDate\n      - fieldname: targetEndDate\n      - fieldname: actualStartDate\n      - fieldname: actualEndDate\n      - fieldname: durationDays\n        description: Planned duration in working days\n      - fieldname: predecessorSubStage\n        description: Name or number of the sub-stage that must complete before this one\n  sses-form:\n    fields:\n      - fieldname: deliverables\n        description: Key outputs expected from this sub-stage — comma-separated\n      - fieldname: acceptanceCriteria\n        description: Criteria for sign-off of this sub-stage\n      - fieldname: userGroupScope\n        description: "Which user groups are included — e.g. internal only